export default {"file":"admin-timetable.html","title":"Admin Timetable","htmlClass":"","bodyClass":"sx-admin-tool","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"sx-loader-card\" aria-label=\"Loading page\">\r\n    <div class=\"sx-loader-mark\"></div>\r\n    <div class=\"sx-loader-title\">Schoolix Timetable</div>\r\n    <div class=\"sx-loader-subtitle\">Preparing classes and teachers...</div>\r\n    <div class=\"sx-loader-bar\"></div>\r\n  </section>\r\n</div>\r\n\r\n<!-- LOADING -->\r\n<div class=\"loading-overlay\" id=\"loadingOverlay\">\r\n  <div class=\"loader\">\r\n    <div class=\"spinner\"></div>\r\n    <p id=\"loadingText\">Loading data...</p>\r\n  </div>\r\n</div>\r\n\r\n<!-- TOAST -->\r\n<div class=\"toast\" id=\"toast\">\r\n  <span class=\"toast-icon\" id=\"toastIcon\"></span>\r\n  <span id=\"toastMsg\"></span>\r\n</div>\r\n\r\n<div class=\"subjects-modal\" id=\"syncTimeModal\" aria-hidden=\"true\">\r\n  <div class=\"subjects-panel\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"syncTimeModalTitle\">\r\n    <div class=\"subjects-panel-head\">\r\n      <div>\r\n        <div class=\"subjects-title\" id=\"syncTimeModalTitle\">Sync Period Time</div>\r\n        <div class=\"subjects-meta\" id=\"syncTimeModalMeta\">Choose class and section to copy period timings from.</div>\r\n      </div>\r\n      <button class=\"btn btn-secondary subject-delete-btn\" onclick=\"closeSyncTimeModal()\" aria-label=\"Close sync time\">\r\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\r\n          <line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/>\r\n        </svg>\r\n      </button>\r\n    </div>\r\n    <div class=\"subjects-body\">\r\n      <div class=\"sync-time-grid\">\r\n        <div class=\"field-group\">\r\n          <label>Class</label>\r\n          <select id=\"syncClassSelect\" onchange=\"populateSyncSectionSelect()\">\r\n            <option value=\"\">Select Class</option>\r\n          </select>\r\n        </div>\r\n        <div class=\"field-group\">\r\n          <label>Section</label>\r\n          <select id=\"syncSectionSelect\">\r\n            <option value=\"\">Select Section</option>\r\n          </select>\r\n        </div>\r\n      </div>\r\n      <div class=\"sync-time-note\">Only period start and end times will be copied. Subjects and teachers in this timetable will stay the same.</div>\r\n    </div>\r\n    <div class=\"subjects-panel-actions\">\r\n      <button class=\"btn btn-secondary\" onclick=\"closeSyncTimeModal()\">Cancel</button>\r\n      <button class=\"btn btn-success\" onclick=\"syncTimeFromSelectedTimetable()\">Sync Time</button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- MAIN -->\r\n<div class=\"main\">\r\n\r\n  <!-- PAGE HEADER -->\r\n  <div class=\"page-header\">\r\n    <h1>\r\n      <svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"vertical-align:-4px;margin-right:8px;color:var(--accent)\">\r\n        <rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"/>\r\n        <line x1=\"16\" y1=\"2\" x2=\"16\" y2=\"6\"/><line x1=\"8\" y1=\"2\" x2=\"8\" y2=\"6\"/>\r\n        <line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"/>\r\n      </svg>\r\n      Class Timetable\r\n    </h1>\r\n    <p>Create and manage weekly schedules for each class section with subjects, teachers, and timings.</p>\r\n  </div>\r\n\r\n  <!-- CONTROLS -->\r\n  <div class=\"control-card\">\r\n    <div class=\"field-group\">\r\n      <label>\r\n        <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\r\n        Class\r\n      </label>\r\n      <select id=\"classSelect\">\r\n        <option value=\"\">Select Class</option>\r\n      </select>\r\n    </div>\r\n    <div class=\"field-group\">\r\n      <label>\r\n        <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg>\r\n        Section\r\n      </label>\r\n      <select id=\"sectionSelect\">\r\n        <option value=\"\">Select Section</option>\r\n      </select>\r\n    </div>\r\n    <div class=\"field-group\">\r\n      <label>\r\n        <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></svg>\r\n        View Teacher Timetable\r\n      </label>\r\n      <select id=\"teacherViewSelect\">\r\n        <option value=\"\">Select Teacher</option>\r\n      </select>\r\n    </div>\r\n    <div class=\"actions\">\r\n      <button class=\"btn btn-primary\" onclick=\"loadTimetable()\">\r\n        <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\r\n          <polyline points=\"1 4 1 10 7 10\"/><path d=\"M3.51 15a9 9 0 1 0 .49-4.18\"/>\r\n        </svg>\r\n        Load Timetable\r\n      </button>\r\n      <button class=\"btn btn-secondary\" onclick=\"addPeriod()\">\r\n        <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\r\n          <circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"16\"/><line x1=\"8\" y1=\"12\" x2=\"16\" y2=\"12\"/>\r\n        </svg>\r\n        Add Period\r\n      </button>\r\n      <button class=\"btn btn-secondary\" onclick=\"openSyncTimeModal()\">\r\n        <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n          <circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/><path d=\"M4 4v5h5\"/>\r\n        </svg>\r\n        Sync Time\r\n      </button>\r\n      <button class=\"btn btn-success\" onclick=\"saveTimetable()\">\r\n        <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\r\n          <path d=\"M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z\"/><polyline points=\"17 21 17 13 7 13 7 21\"/><polyline points=\"7 3 7 8 15 8\"/>\r\n        </svg>\r\n        Save Timetable\r\n      </button>\r\n      <button class=\"btn btn-secondary\" onclick=\"viewTeacherTimetable()\">\r\n        <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\r\n          <path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8S1 12 1 12z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/>\r\n        </svg>\r\n        View Teacher\r\n      </button>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"teacher-view-card\" id=\"teacherViewCard\">\r\n    <div class=\"teacher-view-head\">\r\n      <div>\r\n        <div class=\"teacher-view-title\" id=\"teacherViewTitle\">Teacher Timetable</div>\r\n        <div class=\"teacher-view-meta\" id=\"teacherViewMeta\"></div>\r\n      </div>\r\n      <button class=\"btn btn-secondary\" onclick=\"closeTeacherTimetableView()\">Close View</button>\r\n    </div>\r\n    <div id=\"teacherTimetableView\"></div>\r\n  </div>\r\n\r\n  <!-- STATS BAR -->\r\n  <div class=\"stats-bar\" id=\"statsBar\" style=\"display:none\">\r\n    <div class=\"stat-chip\">\r\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"2\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"/><line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"/></svg>\r\n      <span>Class:</span> <strong id=\"statClass\">—</strong>\r\n    </div>\r\n    <div class=\"stat-chip\">\r\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"2\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg>\r\n      <span>Section:</span> <strong id=\"statSection\" style=\"color:var(--gold)\">—</strong>\r\n    </div>\r\n    <div class=\"stat-chip\">\r\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--green)\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n      <span>Periods:</span> <strong id=\"statPeriods\" style=\"color:var(--green)\">0</strong>\r\n    </div>\r\n    <div class=\"stat-chip\">\r\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--muted)\" stroke-width=\"2\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></svg>\r\n      <span>Days:</span> <strong style=\"color:var(--muted)\">6</strong>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- TIMETABLE AREA -->\r\n  <div id=\"timetableContainer\">\r\n    <div class=\"empty-state\">\r\n      <svg width=\"64\" height=\"64\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\">\r\n        <rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"/>\r\n        <line x1=\"16\" y1=\"2\" x2=\"16\" y2=\"6\"/><line x1=\"8\" y1=\"2\" x2=\"8\" y2=\"6\"/>\r\n        <line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"/>\r\n      </svg>\r\n      <h3>No Timetable Loaded</h3>\r\n      <p>Select a class and section above, then click \"Load Timetable\" to get started.</p>\r\n    </div>\r\n  </div>\r\n\r\n</div>\r\n\r\n<script type=\"module\">\r\n  import { initializeApp }          from \"./firebase-compat.js\";\r\n  import { getAuth, onAuthStateChanged } from \"./firebase-compat.js\";\r\n  import {\r\n    getFirestore, collection, getDocs,\r\n    query, where, doc, getDoc, setDoc, serverTimestamp\r\n  } from \"./firebase-compat.js\";\r\n\r\n  // ── FIREBASE ──\r\n  const firebaseConfig = {\r\n    apiKey:            \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n    authDomain:        \"schoolix-48107.firebaseapp.com\",\r\n    projectId:         \"schoolix-48107\",\r\n    storageBucket:     \"schoolix-48107.firebasestorage.app\",\r\n    messagingSenderId: \"133937954491\",\r\n    appId:             \"1:133937954491:web:69d8064422617eb8c4339e\"\r\n  };\r\n  const app  = initializeApp(firebaseConfig);\r\n  const auth = getAuth(app);\r\n  const db   = getFirestore(app);\r\n\r\n  let currentUser      = null;\r\n  let teachers         = [];\r\n  let allStudents      = [];\r\n  let currentTimetable = null;\r\n  let currentClassSubjects = [];\r\n  let allTimetables = [];\r\n  let timetableCachePromise = null;\r\n  let timetableCacheAt = 0;\r\n  let loadClassesRun = 0;\r\n\r\n  const days = [\"Monday\",\"Tuesday\",\"Wednesday\",\"Thursday\",\"Friday\",\"Saturday\"];\r\n\r\n  // ── HELPERS ──\r\n  function showLoading(on, message = \"Loading data...\") {\r\n    const overlay = document.getElementById(\"loadingOverlay\");\r\n    const text = document.getElementById(\"loadingText\");\r\n    if (text) text.textContent = message;\r\n    overlay.classList.toggle(\"show\", on);\r\n  }\r\n  function nextPaint() {\r\n    return new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));\r\n  }\r\n  function toast(msg, type = \"success\") {\r\n    const t    = document.getElementById(\"toast\");\r\n    const icon = document.getElementById(\"toastIcon\");\r\n    document.getElementById(\"toastMsg\").textContent = msg;\r\n    t.className = `toast ${type} show`;\r\n    icon.innerHTML = type === \"success\"\r\n      ? `<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>`\r\n      : `<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"16\"/><line x1=\"12\" y1=\"20\" x2=\"12.01\" y2=\"20\"/></svg>`;\r\n    clearTimeout(t._timer);\r\n    t._timer = setTimeout(() => t.classList.remove(\"show\"), 3000);\r\n  }\r\n\r\n  // ── LOAD CLASSES ──\r\n  function cleanText(value) {\r\n    return String(value || \"\").replace(/\\s+/g, \" \").trim();\r\n  }\r\n\r\n  function canonicalClass(value) {\r\n    return cleanText(value);\r\n  }\r\n\r\n  function canonicalSection(value) {\r\n    return cleanText(value).toUpperCase();\r\n  }\r\n\r\n  function normalizeIdentity(value) {\r\n    return cleanText(value).toLowerCase();\r\n  }\r\n\r\n  function teacherIdentityKey(teacher = {}) {\r\n    const legacyUid = normalizeIdentity(teacher.legacyUid || teacher.firebaseUid);\r\n    if (legacyUid) return `uid:${legacyUid}`;\r\n    const teacherId = normalizeIdentity(teacher.teacherId);\r\n    if (teacherId) return `teacherId:${teacherId}`;\r\n    const email = normalizeIdentity(teacher.email || teacher.authEmail);\r\n    if (email) return `email:${email}`;\r\n    return `doc:${normalizeIdentity(teacher.uid || teacher.docId)}`;\r\n  }\r\n\r\n  function teacherScore(teacher = {}) {\r\n    const docId = cleanText(teacher.docId || teacher.uid);\r\n    const legacyUid = cleanText(teacher.legacyUid || teacher.firebaseUid);\r\n    const isMirror = Boolean(legacyUid && docId && legacyUid !== docId);\r\n    return (isMirror ? 0 : 100)\r\n      + (teacher.removedFromPanel === true || teacher.panelStatus === \"removed\" || teacher.active === false ? 0 : 10)\r\n      + (teacher.teacherId ? 4 : 0)\r\n      + (teacher.name ? 2 : 0);\r\n  }\r\n\r\n  function dedupeTeachers(list = []) {\r\n    const byIdentity = new Map();\r\n    list.forEach(teacher => {\r\n      const key = teacherIdentityKey(teacher);\r\n      const current = byIdentity.get(key);\r\n      if (!current || teacherScore(teacher) > teacherScore(current)) {\r\n        byIdentity.set(key, teacher);\r\n      }\r\n    });\r\n    return [...byIdentity.values()];\r\n  }\r\n\r\n  function timetableKey(timetable = {}) {\r\n    const className = canonicalClass(timetable.class || String(timetable.id || \"\").split(\"-\")[0]);\r\n    const sectionName = canonicalSection(timetable.section || String(timetable.id || \"\").split(\"-\").slice(1).join(\"-\"));\r\n    if (className || sectionName) return `${className}|${sectionName}`;\r\n    return cleanText(timetable.id);\r\n  }\r\n\r\n  function dedupeTimetables(list = []) {\r\n    const byClassSection = new Map();\r\n    list.forEach(timetable => {\r\n      const key = timetableKey(timetable);\r\n      if (!key) return;\r\n      const current = byClassSection.get(key);\r\n      if (!current || String(timetable.updatedAt || \"\").localeCompare(String(current.updatedAt || \"\")) >= 0) {\r\n        byClassSection.set(key, timetable);\r\n      }\r\n    });\r\n    return [...byClassSection.values()];\r\n  }\r\n\r\n  function createSelectOption(value, label = value) {\r\n    const option = document.createElement(\"option\");\r\n    option.value = value;\r\n    option.textContent = label;\r\n    return option;\r\n  }\r\n\r\n  function replaceSelectOptions(select, placeholder, values = [], selectedValue = \"\") {\r\n    if (!select) return;\r\n    const options = [\r\n      createSelectOption(\"\", placeholder),\r\n      ...values.map(value => createSelectOption(value))\r\n    ];\r\n    select.replaceChildren(...options);\r\n    if (selectedValue && values.some(value => String(value) === String(selectedValue))) {\r\n      select.value = selectedValue;\r\n    }\r\n  }\r\n\r\n  async function loadClasses() {\r\n    const runId = ++loadClassesRun;\r\n    const classSelect   = document.getElementById(\"classSelect\");\r\n    const sectionSelect = document.getElementById(\"sectionSelect\");\r\n    if (!classSelect || !sectionSelect) return;\r\n    const previousClass = classSelect.value;\r\n    const previousSection = sectionSelect.value;\r\n\r\n    const snap = await getDocs(collection(db, \"schools\", currentUser.uid, \"students\"));\r\n    const nextStudents = [];\r\n    snap.forEach(d => {\r\n      const data = d.data();\r\n      const className = canonicalClass(data.class);\r\n      const sectionName = canonicalSection(data.section);\r\n      if (className && sectionName)\r\n        nextStudents.push({ class: className, section: sectionName });\r\n    });\r\n    const seenPlacements = new Set();\r\n    const uniquePlacements = nextStudents.filter(student => {\r\n      const key = `${student.class}|${student.section}`;\r\n      if (seenPlacements.has(key)) return false;\r\n      seenPlacements.add(key);\r\n      return true;\r\n    });\r\n    if (runId !== loadClassesRun) return;\r\n    allStudents = uniquePlacements;\r\n\r\n    const uniqueClasses = [...new Set(allStudents.map(s => s.class))];\r\n    uniqueClasses.sort((a, b) => (parseInt(a) || 0) - (parseInt(b) || 0));\r\n\r\n    const renderSections = (selectedSection = \"\") => {\r\n      const sel = classSelect.value;\r\n      const sections = [...new Set(allStudents.filter(s => s.class === sel).map(s => s.section))];\r\n      sections.sort();\r\n      replaceSelectOptions(sectionSelect, \"Select Section\", sections, selectedSection);\r\n    };\r\n\r\n    replaceSelectOptions(classSelect, \"Select Class\", uniqueClasses, previousClass);\r\n    renderSections(classSelect.value === previousClass ? previousSection : \"\");\r\n\r\n    classSelect.onchange = () => {\r\n      renderSections(\"\");\r\n    };\r\n  }\r\n\r\n  // ── LOAD TEACHERS ──\r\n  async function loadTeachers() {\r\n    const nextTeachers = [];\r\n    const q    = query(collection(db, \"users\"), where(\"role\",\"==\",\"teacher\"), where(\"adminId\",\"==\",currentUser.uid));\r\n    const snap = await getDocs(q);\r\n    snap.forEach(d => {\r\n      const data = d.data() || {};\r\n      const rawSubjects = data.subjects || (data.subject ? [data.subject] : []);\r\n      const subjectsList = Array.isArray(rawSubjects) ? rawSubjects : [rawSubjects];\r\n      nextTeachers.push({\r\n        uid: d.id,\r\n        docId: d.id,\r\n        teacherId: data.teacherId || \"\",\r\n        email: cleanText(data.email || \"\"),\r\n        authEmail: cleanText(data.authEmail || \"\"),\r\n        name: cleanText(data.name || \"Teacher\"),\r\n        subjects: subjectsList.map(s => String(s).trim()).filter(Boolean),\r\n        legacyUid: data.legacyUid || \"\",\r\n        firebaseUid: data.firebaseUid || \"\",\r\n        panelStatus: data.panelStatus || \"\",\r\n        removedFromPanel: data.removedFromPanel === true,\r\n        active: data.active !== false\r\n      });\r\n    });\r\n    teachers = dedupeTeachers(nextTeachers)\r\n      .filter(teacher => teacher.removedFromPanel !== true && teacher.panelStatus !== \"removed\" && teacher.active !== false);\r\n    populateTeacherViewSelect();\r\n  }\r\n\r\n  function populateTeacherViewSelect() {\r\n    const sel = document.getElementById(\"teacherViewSelect\");\r\n    if (!sel) return;\r\n    sel.innerHTML = `<option value=\"\">Select Teacher</option>`;\r\n    teachers\r\n      .slice()\r\n      .sort((a, b) => String(a.name || \"\").localeCompare(String(b.name || \"\")))\r\n      .forEach(teacher => {\r\n        const opt = document.createElement(\"option\");\r\n        opt.value = teacher.uid;\r\n        opt.textContent = `${teacher.name} (${teacher.teacherId || teacher.uid})`;\r\n        sel.appendChild(opt);\r\n      });\r\n  }\r\n\r\n  function findTeacherBySlot(slot = {}) {\r\n    const candidates = [slot.teacherUid, slot.teacherId, slot.teacher, slot.teacherEmail]\r\n      .map(v => String(v || \"\").trim().toLowerCase())\r\n      .filter(Boolean);\r\n    return teachers.find(t => {\r\n      const ids = [t.uid, t.teacherId, t.email, t.name]\r\n        .map(v => String(v || \"\").trim().toLowerCase())\r\n        .filter(Boolean);\r\n      return candidates.some(candidate => ids.includes(candidate));\r\n    }) || null;\r\n  }\r\n\r\n  function hasTeacherReference(slot = {}) {\r\n    return [slot.teacherUid, slot.teacherId, slot.teacherName, slot.teacherEmail, slot.teacher]\r\n      .some(value => cleanText(value));\r\n  }\r\n\r\n  function clearTeacherReference(slot = {}) {\r\n    slot.teacherUid = \"\";\r\n    slot.teacherId = \"\";\r\n    slot.teacherName = \"\";\r\n    slot.teacherEmail = \"\";\r\n    if (\"teacher\" in slot) slot.teacher = \"\";\r\n    return slot;\r\n  }\r\n\r\n  function clearInactiveTeacherSlots(schedule = currentTimetable?.schedule) {\r\n    if (!schedule) return;\r\n    Object.values(schedule || {}).forEach(daySlots => {\r\n      Object.values(daySlots || {}).forEach(slot => {\r\n        if (hasTeacherReference(slot) && !findTeacherBySlot(slot)) clearTeacherReference(slot);\r\n      });\r\n    });\r\n  }\r\n\r\n  function getTeacherReadableId(slot = {}) {\r\n    const teacher = findTeacherBySlot(slot);\r\n    return teacher?.teacherId || slot.teacherReadableId || slot.teacherId || slot.teacherUid || \"—\";\r\n  }\r\n\r\n  function slotBelongsToTeacher(slot = {}, teacher = {}) {\r\n    const slotIds = [slot.teacherUid, slot.teacherId, slot.teacher, slot.teacherEmail, slot.teacherName]\r\n      .map(v => String(v || \"\").trim().toLowerCase())\r\n      .filter(Boolean);\r\n    const teacherIds = [teacher.uid, teacher.teacherId, teacher.email, teacher.name]\r\n      .map(v => String(v || \"\").trim().toLowerCase())\r\n      .filter(Boolean);\r\n    return slotIds.some(id => teacherIds.includes(id));\r\n  }\r\n\r\n  // ── EMPTY SCHEDULE ──\r\n  function createEmptySchedule() {\r\n    const schedule = {};\r\n    days.forEach(day => {\r\n      schedule[day] = {};\r\n      for (let i = 1; i <= 7; i++) {\r\n        schedule[day][`Period ${i}`] = { subject: \"\", teacherUid: \"\", teacherId: \"\", teacherName: \"\" };\r\n      }\r\n    });\r\n    return schedule;\r\n  }\r\n\r\n  function createEmptyPeriodTimes(count = 7) {\r\n    const periodTimes = {};\r\n    for (let i = 1; i <= count; i++) {\r\n      periodTimes[`Period ${i}`] = { startTime: \"\", endTime: \"\" };\r\n    }\r\n    return periodTimes;\r\n  }\r\n\r\n  function getSortedPeriodKeys(schedule = currentTimetable?.schedule) {\r\n    return Object.keys(schedule?.Monday || {})\r\n      .sort((a,b) => parseInt(a.replace(\"Period \",\"\")) - parseInt(b.replace(\"Period \",\"\")));\r\n  }\r\n\r\n  function normalizeTimetablePeriods() {\r\n    if (!currentTimetable?.schedule) return;\r\n    const orderedPeriods = getSortedPeriodKeys();\r\n    const normalized = {};\r\n    const normalizedTimes = {};\r\n    days.forEach(day => { normalized[day] = {}; });\r\n\r\n    orderedPeriods.forEach((period, index) => {\r\n      const nextKey = `Period ${index + 1}`;\r\n      const savedTime = currentTimetable.periodTimes?.[period] || {};\r\n      const legacyTimeSlot = days\r\n        .map(day => currentTimetable.schedule[day]?.[period])\r\n        .find(slot => slot?.startTime || slot?.endTime) || {};\r\n      normalizedTimes[nextKey] = {\r\n        startTime: savedTime.startTime || legacyTimeSlot.startTime || \"\",\r\n        endTime: savedTime.endTime || legacyTimeSlot.endTime || \"\"\r\n      };\r\n      days.forEach(day => {\r\n        const slot = currentTimetable.schedule[day]?.[period] || {};\r\n        const matchedTeacher = findTeacherBySlot(slot);\r\n        const teacherFields = matchedTeacher ? {\r\n          teacherUid: slot.teacherUid || matchedTeacher.uid || \"\",\r\n          teacherId: matchedTeacher.teacherId || slot.teacherId || \"\",\r\n          teacherName: slot.teacherName || matchedTeacher.name || \"\",\r\n          teacherEmail: slot.teacherEmail || matchedTeacher.email || \"\"\r\n        } : {\r\n          teacherUid: \"\",\r\n          teacherId: \"\",\r\n          teacherName: \"\",\r\n          teacherEmail: \"\"\r\n        };\r\n        normalized[day][nextKey] = {\r\n          subject: slot.subject || \"\",\r\n          ...teacherFields\r\n        };\r\n      });\r\n    });\r\n\r\n    currentTimetable.schedule = normalized;\r\n    currentTimetable.periodTimes = normalizedTimes;\r\n    syncPeriodTimesToSlots();\r\n  }\r\n\r\n  function getPeriodTime(period) {\r\n    currentTimetable.periodTimes = currentTimetable.periodTimes || {};\r\n    currentTimetable.periodTimes[period] = currentTimetable.periodTimes[period] || { startTime: \"\", endTime: \"\" };\r\n    return currentTimetable.periodTimes[period];\r\n  }\r\n\r\n  function syncPeriodTimesToSlots() {\r\n    if (!currentTimetable?.schedule) return;\r\n    getSortedPeriodKeys().forEach(period => {\r\n      const time = getPeriodTime(period);\r\n      days.forEach(day => {\r\n        currentTimetable.schedule[day][period] = currentTimetable.schedule[day][period] || {};\r\n        currentTimetable.schedule[day][period].startTime = time.startTime || \"\";\r\n        currentTimetable.schedule[day][period].endTime = time.endTime || \"\";\r\n      });\r\n    });\r\n  }\r\n\r\n  // ── LOAD TIMETABLE ──\r\n  function extractPeriodTimes(timetable = {}) {\r\n    const schedule = timetable.schedule || {};\r\n    const sourcePeriods = sortPeriodKeys([\r\n      ...new Set([\r\n        ...Object.keys(timetable.periodTimes || {}),\r\n        ...Object.keys(schedule.Monday || {})\r\n      ])\r\n    ]);\r\n    const extracted = {};\r\n    sourcePeriods.forEach((period, index) => {\r\n      const targetPeriod = `Period ${index + 1}`;\r\n      const savedTime = timetable.periodTimes?.[period] || {};\r\n      const legacyTimeSlot = days\r\n        .map(day => schedule[day]?.[period])\r\n        .find(slot => slot?.startTime || slot?.endTime) || {};\r\n      extracted[targetPeriod] = {\r\n        startTime: savedTime.startTime || legacyTimeSlot.startTime || \"\",\r\n        endTime: savedTime.endTime || legacyTimeSlot.endTime || \"\"\r\n      };\r\n    });\r\n    return extracted;\r\n  }\r\n\r\n  function normalizeSubjectName(value) {\r\n    return String(value || \"\").replace(/\\s+/g, \" \").trim();\r\n  }\r\n\r\n  function mergeSubjects(...lists) {\r\n    const seen = new Set();\r\n    const subjects = [];\r\n    lists.flat().forEach(value => {\r\n      const name = normalizeSubjectName(typeof value === \"string\" ? value : value?.name);\r\n      const key = name.toLowerCase();\r\n      if (!name || seen.has(key)) return;\r\n      seen.add(key);\r\n      subjects.push(name);\r\n    });\r\n    return subjects.sort((a, b) => a.localeCompare(b));\r\n  }\r\n\r\n  function collectSubjectsFromSchedule(schedule = currentTimetable?.schedule) {\r\n    const subjects = [];\r\n    Object.values(schedule || {}).forEach(daySlots => {\r\n      Object.values(daySlots || {}).forEach(slot => subjects.push(slot?.subject || \"\"));\r\n    });\r\n    return mergeSubjects(subjects);\r\n  }\r\n\r\n  function classSubjectDocId(className = currentTimetable?.class) {\r\n    return `timetable-${String(className || \"\").replace(/[^a-zA-Z0-9_-]/g, \"_\")}`;\r\n  }\r\n\r\n  function classSubjectsRef(className = currentTimetable?.class) {\r\n    return doc(db, \"schools\", currentUser.uid, \"subjects\", classSubjectDocId(className));\r\n  }\r\n\r\n  async function refreshTimetableCache(force = false) {\r\n    if (!currentUser) return allTimetables;\r\n    const cacheIsFresh = allTimetables.length && (Date.now() - timetableCacheAt < 60000);\r\n    if (!force && cacheIsFresh) return allTimetables;\r\n    if (!force && timetableCachePromise) return timetableCachePromise;\r\n    timetableCachePromise = getDocs(collection(db, \"schools\", currentUser.uid, \"timetables\"))\r\n      .then(snapshot => {\r\n        allTimetables = dedupeTimetables(snapshot.docs.map(item => ({ id: item.id, ...(item.data() || {}) })));\r\n        timetableCacheAt = Date.now();\r\n        return allTimetables;\r\n      })\r\n      .finally(() => { timetableCachePromise = null; });\r\n    return timetableCachePromise;\r\n  }\r\n\r\n  let schoolSubjects = [];\r\n\r\n  async function loadSchoolSubjects() {\r\n    if (!currentUser) return [];\r\n    try {\r\n      const snap = await getDocs(collection(db, \"schools\", currentUser.uid, \"subjects\"));\r\n      const list = [];\r\n      snap.forEach(d => {\r\n        const data = d.data() || {};\r\n        const name = normalizeSubjectName(data.name || \"\");\r\n        if (name) list.push(name);\r\n      });\r\n      schoolSubjects = mergeSubjects(list);\r\n    } catch (e) {\r\n      console.warn(\"Failed to load school subjects from Firestore:\", e);\r\n    }\r\n    return schoolSubjects;\r\n  }\r\n\r\n  function subjectOptions(selected = \"\") {\r\n    const selectedName = normalizeSubjectName(selected);\r\n    const subjects = mergeSubjects(schoolSubjects, selectedName ? [selectedName] : []);\r\n    const options = [`<option value=\"\">Select subject</option>`];\r\n    subjects.forEach(subject => {\r\n      const isSelected = subject.toLowerCase() === selectedName.toLowerCase() ? \" selected\" : \"\";\r\n      options.push(`<option value=\"${escHtml(subject)}\"${isSelected}>${escHtml(subject)}</option>`);\r\n    });\r\n    if (!subjects.length) options.push(`<option value=\"\" disabled>No school subjects found</option>`);\r\n    return options.join(\"\");\r\n  }\r\n\r\n  function getTeachersForSubject(subject) {\r\n    if (!subject) return teachers;\r\n    const target = String(subject).trim().toLowerCase();\r\n    return teachers.filter(t => {\r\n      const subList = Array.isArray(t.subjects) ? t.subjects : (t.subject ? [t.subject] : []);\r\n      return subList.some(s => String(s).trim().toLowerCase() === target);\r\n    });\r\n  }\r\n\r\n  function teacherSelectOptions(subject = \"\", selectedTeacherUid = \"\", day = \"\", period = \"\") {\r\n    const cleanSubj = String(subject || \"\").trim();\r\n    const matching = getTeachersForSubject(cleanSubj);\r\n    const options = [`<option value=\"\">Select teacher</option>`];\r\n    const isTeacherSelected = (t) => {\r\n      if (!selectedTeacherUid) return false;\r\n      const target = String(selectedTeacherUid).toLowerCase();\r\n      return (t.uid && t.uid.toLowerCase() === target) ||\r\n             (t.teacherId && t.teacherId.toLowerCase() === target) ||\r\n             (t.name && t.name.toLowerCase() === target);\r\n    };\r\n\r\n    if (cleanSubj && matching.length > 0) {\r\n      matching.forEach(t => {\r\n        const isSelected = isTeacherSelected(t);\r\n        const conflict = (day && period) ? findTeacherConflict(t, day, period) : null;\r\n        options.push(`<option value=\"${t.uid}\"${isSelected ? \" selected\" : \"\"}>${escHtml(t.name)} (${escHtml(t.teacherId || t.uid)})${conflict ? \" [Busy]\" : \"\"}</option>`);\r\n      });\r\n      const otherTeachers = teachers.filter(t => !matching.some(m => m.uid === t.uid));\r\n      if (otherTeachers.length > 0) {\r\n        options.push(`<optgroup label=\"Other Teachers\">`);\r\n        otherTeachers.forEach(t => {\r\n          const isSelected = isTeacherSelected(t);\r\n          const conflict = (day && period) ? findTeacherConflict(t, day, period) : null;\r\n          options.push(`<option value=\"${t.uid}\"${isSelected ? \" selected\" : \"\"}>${escHtml(t.name)} (${escHtml(t.teacherId || t.uid)})${conflict ? \" [Busy]\" : \"\"}</option>`);\r\n        });\r\n        options.push(`</optgroup>`);\r\n      }\r\n    } else if (cleanSubj && matching.length === 0) {\r\n      options.push(`<option value=\"\" disabled>-- No teacher assigned for \"${escHtml(cleanSubj)}\" --</option>`);\r\n      if (teachers.length > 0) {\r\n        options.push(`<optgroup label=\"All Teachers\">`);\r\n        teachers.forEach(t => {\r\n          const isSelected = isTeacherSelected(t);\r\n          const conflict = (day && period) ? findTeacherConflict(t, day, period) : null;\r\n          options.push(`<option value=\"${t.uid}\"${isSelected ? \" selected\" : \"\"}>${escHtml(t.name)} (${escHtml(t.teacherId || t.uid)})${conflict ? \" [Busy]\" : \"\"}</option>`);\r\n        });\r\n        options.push(`</optgroup>`);\r\n      }\r\n    } else {\r\n      teachers.forEach(t => {\r\n        const isSelected = isTeacherSelected(t);\r\n        const conflict = (day && period) ? findTeacherConflict(t, day, period) : null;\r\n        options.push(`<option value=\"${t.uid}\"${isSelected ? \" selected\" : \"\"}>${escHtml(t.name)} (${escHtml(t.teacherId || t.uid)})${conflict ? \" [Busy]\" : \"\"}</option>`);\r\n      });\r\n    }\r\n    return options.join(\"\");\r\n  }\r\n\r\n  window.onSlotSubjectChange = function (day, period, select) {\r\n    const subject = select.value || \"\";\r\n    updateSlot(day, period, \"subject\", subject);\r\n    const slotKey = `${day}-${period.replace(/ /g, \"_\")}`;\r\n    const teacherSel = document.getElementById(`tsel-${slotKey}`);\r\n    if (teacherSel) {\r\n      const currentSlot = currentTimetable.schedule?.[day]?.[period] || {};\r\n      const currentTeacherUid = currentSlot.teacherUid || currentSlot.teacherId || currentSlot.teacherName || \"\";\r\n      teacherSel.innerHTML = teacherSelectOptions(subject, currentTeacherUid, day, period);\r\n      \r\n      const matching = getTeachersForSubject(subject);\r\n      const stillMatches = currentTeacherUid && matching.some(t => t.uid === currentTeacherUid || t.teacherId === currentTeacherUid || t.name === currentTeacherUid);\r\n      if (!stillMatches && currentTeacherUid && subject) {\r\n        updateSlot(day, period, \"teacherUid\", \"\");\r\n        updateSlot(day, period, \"teacherId\", \"\");\r\n        updateSlot(day, period, \"teacherName\", \"\");\r\n        updateSlot(day, period, \"teacherEmail\", \"\");\r\n        teacherSel.value = \"\";\r\n        const badge = document.getElementById(`tid-${slotKey}`);\r\n        if (badge) badge.textContent = \"—\";\r\n      }\r\n    }\r\n  };\r\n\r\n  window.onSlotTeacherChange = function (day, period, select) {\r\n    const teacherUid = select.value;\r\n    const slotKey = `${day}-${period.replace(/ /g, \"_\")}`;\r\n    if (!teacherUid) {\r\n      updateSlot(day, period, \"teacherUid\", \"\");\r\n      updateSlot(day, period, \"teacherId\", \"\");\r\n      updateSlot(day, period, \"teacherName\", \"\");\r\n      updateSlot(day, period, \"teacherEmail\", \"\");\r\n      const badge = document.getElementById(`tid-${slotKey}`);\r\n      if (badge) badge.textContent = \"—\";\r\n      return;\r\n    }\r\n    const teacher = teachers.find(t => t.uid === teacherUid);\r\n    if (!teacher) return;\r\n    const conflict = findTeacherConflict(teacher, day, period);\r\n    if (conflict) {\r\n      toast(conflictMessage(teacher, conflict, day, period), \"error\");\r\n      select.value = currentTimetable.schedule?.[day]?.[period]?.teacherUid || \"\";\r\n      return;\r\n    }\r\n    updateSlot(day, period, \"teacherUid\", teacher.uid);\r\n    updateSlot(day, period, \"teacherId\", teacher.teacherId || teacher.uid);\r\n    updateSlot(day, period, \"teacherName\", teacher.name);\r\n    updateSlot(day, period, \"teacherEmail\", teacher.email || \"\");\r\n    const badge = document.getElementById(`tid-${slotKey}`);\r\n    if (badge) badge.textContent = teacher.teacherId || teacher.uid;\r\n  };\r\n\r\n  function getClassOptions() {\r\n    return [...new Set(allStudents.map(student => student.class).filter(Boolean))]\r\n      .sort((a, b) => (parseInt(a, 10) || 0) - (parseInt(b, 10) || 0) || String(a).localeCompare(String(b)));\r\n  }\r\n\r\n  function getSectionOptions(className) {\r\n    return [...new Set(allStudents\r\n      .filter(student => String(student.class) === String(className))\r\n      .map(student => student.section)\r\n      .filter(Boolean))]\r\n      .sort((a, b) => String(a).localeCompare(String(b)));\r\n  }\r\n\r\n  window.populateSyncSectionSelect = function () {\r\n    const className = document.getElementById(\"syncClassSelect\")?.value || \"\";\r\n    const sectionSelect = document.getElementById(\"syncSectionSelect\");\r\n    if (!sectionSelect) return;\r\n    sectionSelect.innerHTML = `<option value=\"\">Select Section</option>`;\r\n    getSectionOptions(className).forEach(section => {\r\n      const option = document.createElement(\"option\");\r\n      option.value = option.textContent = section;\r\n      sectionSelect.appendChild(option);\r\n    });\r\n  };\r\n\r\n  window.openSyncTimeModal = function () {\r\n    if (!currentTimetable) { toast(\"Load a timetable first\", \"error\"); return; }\r\n    const classSelect = document.getElementById(\"syncClassSelect\");\r\n    const meta = document.getElementById(\"syncTimeModalMeta\");\r\n    if (meta) meta.textContent = `Copy timings into Class ${currentTimetable.class}-${currentTimetable.section}`;\r\n    classSelect.innerHTML = `<option value=\"\">Select Class</option>`;\r\n    getClassOptions().forEach(className => {\r\n      const option = document.createElement(\"option\");\r\n      option.value = option.textContent = className;\r\n      classSelect.appendChild(option);\r\n    });\r\n    classSelect.value = currentTimetable.class || \"\";\r\n    populateSyncSectionSelect();\r\n    document.getElementById(\"syncSectionSelect\").value = currentTimetable.section || \"\";\r\n    const modal = document.getElementById(\"syncTimeModal\");\r\n    modal.classList.add(\"show\");\r\n    modal.setAttribute(\"aria-hidden\", \"false\");\r\n  };\r\n\r\n  window.closeSyncTimeModal = function () {\r\n    const modal = document.getElementById(\"syncTimeModal\");\r\n    modal.classList.remove(\"show\");\r\n    modal.setAttribute(\"aria-hidden\", \"true\");\r\n  };\r\n\r\n  window.syncTimeFromSelectedTimetable = async function () {\r\n    if (!currentTimetable) { toast(\"Load a timetable first\", \"error\"); return; }\r\n    const sourceClass = document.getElementById(\"syncClassSelect\")?.value || \"\";\r\n    const sourceSection = document.getElementById(\"syncSectionSelect\")?.value || \"\";\r\n    if (!sourceClass || !sourceSection) { toast(\"Select source class and section\", \"error\"); return; }\r\n    showLoading(true, \"Syncing period times...\");\r\n    try {\r\n      await nextPaint();\r\n      const sourceRef = doc(db, \"schools\", currentUser.uid, \"timetables\", `${sourceClass}-${sourceSection}`);\r\n      const sourceSnap = await getDoc(sourceRef);\r\n      if (!sourceSnap.exists()) {\r\n        toast(\"Selected timetable not found\", \"error\");\r\n        showLoading(false);\r\n        return;\r\n      }\r\n      const sourceTimes = extractPeriodTimes(sourceSnap.data() || {});\r\n      const currentPeriods = getSortedPeriodKeys();\r\n      let synced = 0;\r\n      currentTimetable.periodTimes = currentTimetable.periodTimes || {};\r\n      currentPeriods.forEach(period => {\r\n        const sourceTime = sourceTimes[period];\r\n        if (!sourceTime || (!sourceTime.startTime && !sourceTime.endTime)) return;\r\n        currentTimetable.periodTimes[period] = {\r\n          startTime: sourceTime.startTime || \"\",\r\n          endTime: sourceTime.endTime || \"\"\r\n        };\r\n        synced += 1;\r\n      });\r\n      syncPeriodTimesToSlots();\r\n      renderTimetable();\r\n      closeSyncTimeModal();\r\n      toast(synced ? `Synced ${synced} period time${synced === 1 ? \"\" : \"s\"}` : \"No period times found to sync\", synced ? \"success\" : \"error\");\r\n    } catch(e) {\r\n      console.error(e);\r\n      toast(\"Error syncing period times\", \"error\");\r\n    }\r\n    showLoading(false);\r\n  };\r\n\r\n  function clearSubjectFromSchedule(subject) {\r\n    const target = normalizeSubjectName(subject).toLowerCase();\r\n    if (!target || !currentTimetable?.schedule) return;\r\n    Object.values(currentTimetable.schedule).forEach(daySlots => {\r\n      Object.values(daySlots || {}).forEach(slot => {\r\n        if (normalizeSubjectName(slot?.subject).toLowerCase() === target) slot.subject = \"\";\r\n      });\r\n    });\r\n  }\r\n\r\n  function clearSubjectsNotInClassList() {\r\n    const allowed = new Set(currentClassSubjects.map(subject => subject.toLowerCase()));\r\n    if (!currentTimetable?.schedule) return;\r\n    Object.values(currentTimetable.schedule).forEach(daySlots => {\r\n      Object.values(daySlots || {}).forEach(slot => {\r\n        const subject = normalizeSubjectName(slot?.subject);\r\n        if (subject && !allowed.has(subject.toLowerCase())) slot.subject = \"\";\r\n      });\r\n    });\r\n  }\r\n\r\n  function currentTimetableDocId() {\r\n    if (!currentTimetable) return \"\";\r\n    return `${currentTimetable.class}-${currentTimetable.section}`;\r\n  }\r\n\r\n  function sameTeacher(teacher = {}, slot = {}) {\r\n    const teacherIds = [teacher.uid, teacher.teacherId, teacher.email, teacher.name]\r\n      .map(value => String(value || \"\").trim().toLowerCase())\r\n      .filter(Boolean);\r\n    const slotIds = [slot.teacherUid, slot.teacherId, slot.teacher, slot.teacherEmail, slot.teacherName]\r\n      .map(value => String(value || \"\").trim().toLowerCase())\r\n      .filter(Boolean);\r\n    return teacherIds.some(id => slotIds.includes(id));\r\n  }\r\n\r\n  function findTeacherConflict(teacher, day, period) {\r\n    const currentId = currentTimetableDocId();\r\n    return allTimetables.find(timetable => {\r\n      const timetableId = timetable.id || `${timetable.class || \"\"}-${timetable.section || \"\"}`;\r\n      if (timetableId === currentId) return false;\r\n      const slot = timetable.schedule?.[day]?.[period];\r\n      return slot && sameTeacher(teacher, slot);\r\n    }) || null;\r\n  }\r\n\r\n  function conflictMessage(teacher, conflict, day, period) {\r\n    const classLabel = [conflict?.class, conflict?.section].filter(Boolean).join(\" \");\r\n    return `${teacher.name} already has ${period} on ${day}${classLabel ? ` in Class ${classLabel}` : \"\"}.`;\r\n  }\r\n\r\n  function validateNoTeacherConflicts() {\r\n    if (!currentTimetable?.schedule) return true;\r\n    for (const day of days) {\r\n      const slots = currentTimetable.schedule[day] || {};\r\n      for (const period of Object.keys(slots)) {\r\n        const slot = slots[period] || {};\r\n        const teacher = findTeacherBySlot(slot);\r\n        if (!teacher) continue;\r\n        const conflict = findTeacherConflict(teacher, day, period);\r\n        if (conflict) {\r\n          toast(conflictMessage(teacher, conflict, day, period), \"error\");\r\n          return false;\r\n        }\r\n      }\r\n    }\r\n    return true;\r\n  }\r\n\r\n  window.addClassSubject = function () {\r\n    if (!currentTimetable) { toast(\"Load a timetable first\", \"error\"); return; }\r\n    const input = document.getElementById(\"subjectNameInput\");\r\n    const subject = normalizeSubjectName(input?.value || \"\");\r\n    if (!subject) { toast(\"Enter subject name\", \"error\"); return; }\r\n    currentClassSubjects = mergeSubjects(currentClassSubjects, [subject]);\r\n    currentTimetable.classSubjects = currentClassSubjects;\r\n    if (input) input.value = \"\";\r\n    renderSubjectsModal();\r\n    renderTimetable();\r\n  };\r\n\r\n  window.deleteClassSubject = function (index) {\r\n    const subject = currentClassSubjects[index];\r\n    if (!subject) return;\r\n    currentClassSubjects = currentClassSubjects.filter((_, i) => i !== index);\r\n    clearSubjectFromSchedule(subject);\r\n    currentTimetable.classSubjects = currentClassSubjects;\r\n    renderSubjectsModal();\r\n    renderTimetable();\r\n  };\r\n\r\n  window.saveClassSubjects = async function () {\r\n    if (!currentTimetable) { toast(\"Load a timetable first\", \"error\"); return; }\r\n    showLoading(true, \"Saving subjects...\");\r\n    try {\r\n      await nextPaint();\r\n      currentClassSubjects = mergeSubjects(currentClassSubjects);\r\n      currentTimetable.classSubjects = currentClassSubjects;\r\n      await setDoc(classSubjectsRef(), {\r\n        type: \"timetableClassSubjects\",\r\n        className: currentTimetable.class,\r\n        subjects: currentClassSubjects,\r\n        updatedAt: serverTimestamp()\r\n      });\r\n      const ref = doc(db, \"schools\", currentUser.uid, \"timetables\", `${currentTimetable.class}-${currentTimetable.section}`);\r\n      await setDoc(ref, { ...currentTimetable, updatedAt: serverTimestamp() });\r\n      allTimetables = allTimetables.filter(timetable => (timetable.id || `${timetable.class || \"\"}-${timetable.section || \"\"}`) !== currentTimetableDocId());\r\n      allTimetables.push({ id: currentTimetableDocId(), ...currentTimetable });\r\n      allTimetables = dedupeTimetables(allTimetables);\r\n      toast(\"Subjects saved successfully!\");\r\n    } catch(e) {\r\n      console.error(e);\r\n      toast(\"Error saving subjects\", \"error\");\r\n    }\r\n    showLoading(false);\r\n  };\r\n\r\n  window.loadTimetable = async function () {\r\n    const cls = document.getElementById(\"classSelect\").value;\r\n    const sec = document.getElementById(\"sectionSelect\").value;\r\n    if (!cls || !sec) { toast(\"Please select a class and section\", \"error\"); return; }\r\n    showLoading(true, \"Loading timetable...\");\r\n    try {\r\n      await nextPaint();\r\n      const ref  = doc(db, \"schools\", currentUser.uid, \"timetables\", `${cls}-${sec}`);\r\n      const [snap] = await Promise.all([getDoc(ref), loadSchoolSubjects()]);\r\n      if (snap.exists()) {\r\n        currentTimetable = snap.data();\r\n        currentTimetable.class = currentTimetable.class || cls;\r\n        currentTimetable.section = currentTimetable.section || sec;\r\n        normalizeTimetablePeriods();\r\n        clearInactiveTeacherSlots();\r\n      } else {\r\n        currentTimetable = { class: cls, section: sec, schedule: createEmptySchedule(), periodTimes: createEmptyPeriodTimes() };\r\n        syncPeriodTimesToSlots();\r\n      }\r\n      renderTimetable();\r\n      document.getElementById(\"statsBar\").style.display = \"flex\";\r\n      document.getElementById(\"statClass\").textContent   = cls;\r\n      document.getElementById(\"statSection\").textContent = sec;\r\n      refreshTimetableCache().catch(console.error);\r\n    } catch(e) {\r\n      toast(\"Failed to load timetable\", \"error\");\r\n    }\r\n    showLoading(false);\r\n  };\r\n\r\n  // ── ADD PERIOD ──\r\n  window.addPeriod = function () {\r\n    if (!currentTimetable) { toast(\"Load a timetable first\", \"error\"); return; }\r\n    normalizeTimetablePeriods();\r\n    const periods = getSortedPeriodKeys();\r\n    const next    = periods.length + 1;\r\n    currentTimetable.periodTimes = currentTimetable.periodTimes || {};\r\n    currentTimetable.periodTimes[`Period ${next}`] = { startTime: \"\", endTime: \"\" };\r\n    days.forEach(day => {\r\n      currentTimetable.schedule[day][`Period ${next}`] = { subject: \"\", teacherUid: \"\", teacherId: \"\", teacherName: \"\", startTime: \"\", endTime: \"\" };\r\n    });\r\n    renderTimetable();\r\n    toast(`Period ${next} added`);\r\n  };\r\n\r\n  // ── REMOVE PERIOD ──\r\n  window.removePeriod = function (periodNum) {\r\n    if (!currentTimetable) return;\r\n    const key = `Period ${periodNum}`;\r\n    days.forEach(day => { delete currentTimetable.schedule[day][key]; });\r\n    if (currentTimetable.periodTimes) delete currentTimetable.periodTimes[key];\r\n    normalizeTimetablePeriods();\r\n    renderTimetable();\r\n    toast(`Period ${periodNum} removed`);\r\n  };\r\n\r\n  // ── UPDATE SLOT ──\r\n  window.updateSlot = function (day, period, field, value) {\r\n    currentTimetable.schedule[day][period][field] = value;\r\n    if (field === \"teacherName\") {\r\n      currentTimetable.schedule[day][period].teacherUid = \"\";\r\n      currentTimetable.schedule[day][period].teacherId = \"\";\r\n      currentTimetable.schedule[day][period].teacherEmail = \"\";\r\n      const badge = document.getElementById(`tid-${day}-${period.replace(\" \",\"_\")}`);\r\n      if (badge) badge.textContent = \"—\";\r\n    }\r\n  };\r\n\r\n  window.updatePeriodTime = function (period, field, value) {\r\n    if (![\"startTime\", \"endTime\"].includes(field)) return;\r\n    const time = getPeriodTime(period);\r\n    time[field] = value;\r\n    syncPeriodTimesToSlots();\r\n    updatePeriodTimeDisplay(period);\r\n  };\r\n\r\n  function updatePeriodTimeDisplay(period) {\r\n    const slot = getPeriodTime(period);\r\n    const el   = document.getElementById(`time-display-${period.replace(\" \",\"_\")}`);\r\n    if (!el) return;\r\n    if (slot.startTime && slot.endTime) {\r\n      el.textContent = `${slot.startTime} – ${slot.endTime}`;\r\n    } else if (slot.startTime) {\r\n      el.textContent = `From ${slot.startTime}`;\r\n    } else {\r\n      el.textContent = \"\";\r\n    }\r\n  }\r\n\r\n  // ── SEARCH TEACHER ──\r\n  window.searchTeacher = function (input, day, period) {\r\n    const value     = input.value.toLowerCase();\r\n    const resultBox = document.getElementById(`tr-${day}-${period.replace(\" \",\"_\")}`);\r\n    resultBox.innerHTML = \"\";\r\n    if (!value) return;\r\n    const filtered = teachers.filter(t =>\r\n      (t.name || \"\").toLowerCase().includes(value) ||\r\n      (t.teacherId || \"\").toLowerCase().includes(value)\r\n    );\r\n    filtered.slice(0, 6).forEach(teacher => {\r\n      const conflict = findTeacherConflict(teacher, day, period);\r\n      const div = document.createElement(\"div\");\r\n      div.className = `teacher-result-item${conflict ? \" busy\" : \"\"}`;\r\n      div.innerHTML = `<div class=\"t-name\">${escHtml(teacher.name)}</div><div class=\"t-id\">${conflict ? escHtml(conflictMessage(teacher, conflict, day, period)) : escHtml(teacher.teacherId || teacher.uid)}</div>`;\r\n      div.onclick = () => {\r\n        if (conflict) {\r\n          toast(conflictMessage(teacher, conflict, day, period), \"error\");\r\n          return;\r\n        }\r\n        input.value = teacher.name;\r\n        currentTimetable.schedule[day][period].teacherUid  = teacher.uid;\r\n        currentTimetable.schedule[day][period].teacherId   = teacher.teacherId || teacher.uid;\r\n        currentTimetable.schedule[day][period].teacherName = teacher.name;\r\n        currentTimetable.schedule[day][period].teacherEmail = teacher.email || \"\";\r\n        // Update badge\r\n        const badge = document.getElementById(`tid-${day}-${period.replace(\" \",\"_\")}`);\r\n        if (badge) badge.textContent = teacher.teacherId || teacher.uid;\r\n        resultBox.innerHTML = \"\";\r\n      };\r\n      resultBox.appendChild(div);\r\n    });\r\n  };\r\n\r\n  // ── RENDER ──\r\n  function renderTimetableLegacyDailyTime() {\r\n    const container = document.getElementById(\"timetableContainer\");\r\n    normalizeTimetablePeriods();\r\n    const periods = getSortedPeriodKeys();\r\n\r\n    document.getElementById(\"statPeriods\").textContent = periods.length;\r\n\r\n    const dayIcons = {\r\n      Monday:    `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><line x1=\"12\" y1=\"1\" x2=\"12\" y2=\"3\"/><line x1=\"12\" y1=\"21\" x2=\"12\" y2=\"23\"/><line x1=\"4.22\" y1=\"4.22\" x2=\"5.64\" y2=\"5.64\"/><line x1=\"18.36\" y1=\"18.36\" x2=\"19.78\" y2=\"19.78\"/><line x1=\"1\" y1=\"12\" x2=\"3\" y2=\"12\"/><line x1=\"21\" y1=\"12\" x2=\"23\" y2=\"12\"/><line x1=\"4.22\" y1=\"19.78\" x2=\"5.64\" y2=\"18.36\"/><line x1=\"18.36\" y1=\"5.64\" x2=\"19.78\" y2=\"4.22\"/></svg>`,\r\n      Tuesday:   `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 3v1m0 16v1M4.22 4.22l.707.707m12.728 12.728.707.707M3 12h1m16 0h1M4.927 19.073l.707-.707M18.364 5.636l.707-.707\"/></svg>`,\r\n      Wednesday: `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></svg>`,\r\n      Thursday:  `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg>`,\r\n      Friday:    `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"/><line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"/></svg>`,\r\n      Saturday:  `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 2a10 10 0 1 0 10 10H12z\"/></svg>`,\r\n    };\r\n\r\n    let html = `<div class=\"table-wrapper\"><table>\r\n      <thead><tr>\r\n        <th>Period / Time</th>\r\n        ${days.map(d => `<th><div class=\"day-icon\">${dayIcons[d] || \"\"} ${d}</div></th>`).join(\"\")}\r\n      </tr></thead>\r\n      <tbody>`;\r\n\r\n    periods.forEach(period => {\r\n      const pNum   = period.replace(\"Period \",\"\");\r\n      const pKey   = period.replace(\" \",\"_\");\r\n      const monday = currentTimetable.schedule[\"Monday\"][period];\r\n      const timeDisplay = (monday.startTime && monday.endTime)\r\n        ? `${monday.startTime} – ${monday.endTime}`\r\n        : (monday.startTime ? `From ${monday.startTime}` : \"\");\r\n\r\n      html += `<tr>\r\n        <td>\r\n          <div class=\"period-cell\">\r\n            <div class=\"period-num\">\r\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"2.2\" style=\"vertical-align:-2px;margin-right:4px\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n              ${period}\r\n            </div>\r\n            <div class=\"period-time-display\" id=\"time-display-${pKey}\">${timeDisplay}</div>\r\n            ${periods.length > 1 ? `<button class=\"btn btn-danger period-remove\" onclick=\"removePeriod(${pNum})\">\r\n              <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-1 14H6L5 6\"/><path d=\"M10 11v6\"/><path d=\"M14 11v6\"/><path d=\"M9 6V4h6v2\"/></svg>\r\n              Remove\r\n            </button>` : \"\"}\r\n          </div>\r\n        </td>`;\r\n\r\n      days.forEach(day => {\r\n        const slot    = currentTimetable.schedule[day][period] || {};\r\n        const slotKey = `${day}-${pKey}`;\r\n        html += `<td>\r\n          <div class=\"slot-cell\">\r\n\r\n            <div class=\"field-label-small\">\r\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\r\n              Subject\r\n            </div>\r\n            <input class=\"slot-input subject-input\" type=\"text\" placeholder=\"e.g. Mathematics\"\r\n              value=\"${escHtml(slot.subject || '')}\"\r\n              onchange=\"updateSlot('${day}','${period}','subject',this.value)\">\r\n\r\n            <div class=\"field-label-small\" style=\"margin-top:2px\">\r\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n              <span style=\"color:var(--gold)\">Start</span>\r\n            </div>\r\n            <input class=\"slot-input time-input\" type=\"text\"\r\n              value=\"${escHtml(slot.startTime || '')}\"\r\n              onchange=\"updateSlot('${day}','${period}','startTime',this.value)\">\r\n\r\n            <div class=\"field-label-small\">\r\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n              <span style=\"color:var(--gold)\">End</span>\r\n            </div>\r\n            <input class=\"slot-input time-input\" type=\"text\"\r\n              value=\"${escHtml(slot.endTime || '')}\"\r\n              onchange=\"updateSlot('${day}','${period}','endTime',this.value)\">\r\n\r\n            <div class=\"field-label-small\" style=\"margin-top:2px\">\r\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></svg>\r\n              Teacher\r\n            </div>\r\n            <div class=\"teacher-search-wrap\">\r\n              <input class=\"slot-input\" type=\"text\" placeholder=\"Search teacher…\"\r\n                value=\"${escHtml(slot.teacherName || '')}\"\r\n                oninput=\"updateSlot('${day}','${period}','teacherName',this.value); searchTeacher(this,'${day}','${period}')\">\r\n              <div class=\"teacher-results\" id=\"tr-${slotKey}\"></div>\r\n            </div>\r\n\r\n            <div class=\"teacher-id-badge\">\r\n              <svg width=\"9\" height=\"9\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"2\" y=\"7\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M16 3H8l-2 4h12z\"/></svg>\r\n              <span id=\"tid-${slotKey}\">${escHtml(getTeacherReadableId(slot))}</span>\r\n            </div>\r\n          </div>\r\n        </td>`;\r\n      });\r\n      html += `</tr>`;\r\n    });\r\n\r\n    html += `</tbody></table></div>`;\r\n    container.innerHTML = html;\r\n  }\r\n\r\n  function renderTimetable() {\r\n    const container = document.getElementById(\"timetableContainer\");\r\n    normalizeTimetablePeriods();\r\n    const periods = getSortedPeriodKeys();\r\n\r\n    document.getElementById(\"statPeriods\").textContent = periods.length;\r\n\r\n    const dayIcons = {\r\n      Monday:    `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><line x1=\"12\" y1=\"1\" x2=\"12\" y2=\"3\"/><line x1=\"12\" y1=\"21\" x2=\"12\" y2=\"23\"/><line x1=\"4.22\" y1=\"4.22\" x2=\"5.64\" y2=\"5.64\"/><line x1=\"18.36\" y1=\"18.36\" x2=\"19.78\" y2=\"19.78\"/><line x1=\"1\" y1=\"12\" x2=\"3\" y2=\"12\"/><line x1=\"21\" y1=\"12\" x2=\"23\" y2=\"12\"/><line x1=\"4.22\" y1=\"19.78\" x2=\"5.64\" y2=\"18.36\"/><line x1=\"18.36\" y1=\"5.64\" x2=\"19.78\" y2=\"4.22\"/></svg>`,\r\n      Tuesday:   `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 3v1m0 16v1M4.22 4.22l.707.707m12.728 12.728.707.707M3 12h1m16 0h1M4.927 19.073l.707-.707M18.364 5.636l.707-.707\"/></svg>`,\r\n      Wednesday: `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></svg>`,\r\n      Thursday:  `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg>`,\r\n      Friday:    `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"/><line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"/></svg>`,\r\n      Saturday:  `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 2a10 10 0 1 0 10 10H12z\"/></svg>`\r\n    };\r\n\r\n    let html = `<div class=\"table-wrapper\"><table>\r\n      <thead><tr>\r\n        <th>Period / Time</th>\r\n        ${days.map(d => `<th><div class=\"day-icon\">${dayIcons[d] || \"\"} ${d}</div></th>`).join(\"\")}\r\n      </tr></thead>\r\n      <tbody>`;\r\n\r\n    periods.forEach(period => {\r\n      const pNum = period.replace(\"Period \", \"\");\r\n      const pKey = period.replace(\" \", \"_\");\r\n      const periodTime = getPeriodTime(period);\r\n      const timeDisplay = getTimeLabel(periodTime);\r\n\r\n      html += `<tr>\r\n        <td>\r\n          <div class=\"period-cell\">\r\n            <div class=\"period-num\">\r\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"2.2\" style=\"vertical-align:-2px;margin-right:4px\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n              ${period}\r\n            </div>\r\n            <div class=\"period-time-display\" id=\"time-display-${pKey}\">${escHtml(timeDisplay)}</div>\r\n            <div class=\"period-time-controls\">\r\n              <div class=\"field-label-small\">\r\n                <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n                <span style=\"color:var(--gold)\">Start</span>\r\n              </div>\r\n              <input class=\"slot-input time-input\" type=\"text\" value=\"${escHtml(periodTime.startTime || \"\")}\" onchange=\"updatePeriodTime('${period}','startTime',this.value)\">\r\n              <div class=\"field-label-small\">\r\n                <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n                <span style=\"color:var(--gold)\">End</span>\r\n              </div>\r\n              <input class=\"slot-input time-input\" type=\"text\" value=\"${escHtml(periodTime.endTime || \"\")}\" onchange=\"updatePeriodTime('${period}','endTime',this.value)\">\r\n            </div>\r\n            ${periods.length > 1 ? `<button class=\"btn btn-danger period-remove\" onclick=\"removePeriod(${pNum})\">\r\n              <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-1 14H6L5 6\"/><path d=\"M10 11v6\"/><path d=\"M14 11v6\"/><path d=\"M9 6V4h6v2\"/></svg>\r\n              Remove\r\n            </button>` : \"\"}\r\n          </div>\r\n        </td>`;\r\n\r\n      days.forEach(day => {\r\n        const slot = currentTimetable.schedule[day][period] || {};\r\n        const slotKey = `${day}-${pKey}`;\r\n        html += `<td>\r\n          <div class=\"slot-cell\">\r\n            <div class=\"field-label-small\">\r\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\r\n              Subject\r\n            </div>\r\n            <input class=\"slot-input subject-input\" type=\"text\" placeholder=\"e.g. Mathematics\" value=\"${escHtml(slot.subject || \"\")}\" onchange=\"updateSlot('${day}','${period}','subject',this.value)\">\r\n\r\n            <div class=\"field-label-small\" style=\"margin-top:2px\">\r\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></svg>\r\n              Teacher\r\n            </div>\r\n            <div class=\"teacher-search-wrap\">\r\n              <input class=\"slot-input\" type=\"text\" placeholder=\"Search teacher...\" value=\"${escHtml(slot.teacherName || \"\")}\" oninput=\"updateSlot('${day}','${period}','teacherName',this.value); searchTeacher(this,'${day}','${period}')\">\r\n              <div class=\"teacher-results\" id=\"tr-${slotKey}\"></div>\r\n            </div>\r\n\r\n            <div class=\"teacher-id-badge\">\r\n              <svg width=\"9\" height=\"9\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"2\" y=\"7\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M16 3H8l-2 4h12z\"/></svg>\r\n              <span id=\"tid-${slotKey}\">${escHtml(getTeacherReadableId(slot))}</span>\r\n            </div>\r\n          </div>\r\n        </td>`;\r\n      });\r\n      html += `</tr>`;\r\n    });\r\n\r\n    html += `</tbody></table></div>`;\r\n    container.innerHTML = html;\r\n  }\r\n\r\n  function sortPeriodKeys(periods = []) {\r\n    return periods.slice().sort((a, b) =>\r\n      (parseInt(String(a).replace(\"Period \", \"\"), 10) || 0) -\r\n      (parseInt(String(b).replace(\"Period \", \"\"), 10) || 0)\r\n    );\r\n  }\r\n\r\n  function getTimeLabel(slot = {}) {\r\n    if (slot.startTime && slot.endTime) return `${formatTime12(slot.startTime)} - ${formatTime12(slot.endTime)}`;\r\n    if (slot.startTime) return `From ${formatTime12(slot.startTime)}`;\r\n    if (slot.endTime) return `Until ${formatTime12(slot.endTime)}`;\r\n    return \"\";\r\n  }\r\n\r\n  function formatTime12(value) {\r\n    const match = String(value || \"\").trim().match(/^(\\d{1,2}):(\\d{2})/);\r\n    if (!match) return String(value || \"\");\r\n    let hours = Number(match[1]);\r\n    const minutes = match[2];\r\n    if (!Number.isFinite(hours)) return String(value || \"\");\r\n    const suffix = hours >= 12 ? \"PM\" : \"AM\";\r\n    hours = hours % 12 || 12;\r\n    return `${hours}:${minutes} ${suffix}`;\r\n  }\r\n\r\n  function timeParts12(value) {\r\n    const match = String(value || \"\").trim().match(/^(\\d{1,2}):(\\d{2})/);\r\n    if (!match) return { hour: \"\", minute: \"\", meridiem: \"AM\" };\r\n    const rawHour = Number(match[1]);\r\n    const minute = match[2];\r\n    if (!Number.isFinite(rawHour)) return { hour: \"\", minute: \"\", meridiem: \"AM\" };\r\n    return {\r\n      hour: String(rawHour % 12 || 12),\r\n      minute,\r\n      meridiem: rawHour >= 12 ? \"PM\" : \"AM\"\r\n    };\r\n  }\r\n\r\n  function toTime24(hour, minute, meridiem) {\r\n    let value = Number(hour || 0);\r\n    if (!Number.isFinite(value) || value < 1 || value > 12 || !minute) return \"\";\r\n    const suffix = meridiem === \"PM\" ? \"PM\" : \"AM\";\r\n    if (suffix === \"AM\" && value === 12) value = 0;\r\n    if (suffix === \"PM\" && value !== 12) value += 12;\r\n    return `${String(value).padStart(2, \"0\")}:${String(minute).padStart(2, \"0\")}`;\r\n  }\r\n\r\n  function timeOptions(selectedValue, values) {\r\n    return values.map(value => `<option value=\"${escHtml(value)}\" ${String(value) === String(selectedValue) ? \"selected\" : \"\"}>${escHtml(value)}</option>`).join(\"\");\r\n  }\r\n\r\n  function renderTime12Controls(period, field, value) {\r\n    const parts = timeParts12(value);\r\n    const id = `${period.replace(/\\s+/g, \"_\")}_${field}`;\r\n    const hours = Array.from({ length: 12 }, (_, index) => String(index + 1));\r\n    const minutes = Array.from({ length: 12 }, (_, index) => String(index * 5).padStart(2, \"0\"));\r\n    return `<div class=\"time-12-controls\" data-period=\"${escHtml(period)}\" data-field=\"${escHtml(field)}\">\r\n      <select class=\"slot-input time-input\" id=\"${id}_hour\" aria-label=\"${escHtml(period)} ${field} hour\" onchange=\"updatePeriodTime12('${period}','${field}')\">\r\n        <option value=\"\">Hr</option>${timeOptions(parts.hour, hours)}\r\n      </select>\r\n      <select class=\"slot-input time-input\" id=\"${id}_minute\" aria-label=\"${escHtml(period)} ${field} minute\" onchange=\"updatePeriodTime12('${period}','${field}')\">\r\n        <option value=\"\">Min</option>${timeOptions(parts.minute, minutes)}\r\n      </select>\r\n      <select class=\"slot-input time-input\" id=\"${id}_meridiem\" aria-label=\"${escHtml(period)} ${field} AM PM\" onchange=\"updatePeriodTime12('${period}','${field}')\">\r\n        ${timeOptions(parts.meridiem, [\"AM\", \"PM\"])}\r\n      </select>\r\n    </div>`;\r\n  }\r\n\r\n  window.updatePeriodTime12 = function (period, field) {\r\n    const id = `${period.replace(/\\s+/g, \"_\")}_${field}`;\r\n    const hour = document.getElementById(`${id}_hour`)?.value || \"\";\r\n    const minute = document.getElementById(`${id}_minute`)?.value || \"\";\r\n    const meridiem = document.getElementById(`${id}_meridiem`)?.value || \"AM\";\r\n    updatePeriodTime(period, field, toTime24(hour, minute, meridiem));\r\n  };\r\n\r\n  window.closeTeacherTimetableView = function() {\r\n    document.getElementById(\"teacherViewCard\").classList.remove(\"show\");\r\n    document.getElementById(\"teacherTimetableView\").innerHTML = \"\";\r\n  };\r\n\r\n  window.viewTeacherTimetable = async function() {\r\n    const teacherUid = document.getElementById(\"teacherViewSelect\").value;\r\n    if (!teacherUid) {\r\n      toast(\"Please select a teacher first\", \"error\");\r\n      return;\r\n    }\r\n\r\n    const teacher = teachers.find(t => t.uid === teacherUid);\r\n    if (!teacher) {\r\n      toast(\"Teacher not found\", \"error\");\r\n      return;\r\n    }\r\n\r\n    showLoading(true, \"Loading teacher timetable...\");\r\n    try {\r\n      await nextPaint();\r\n      const timetables = await refreshTimetableCache(true);\r\n      const teacherSchedule = {};\r\n      let slotCount = 0;\r\n      const classSet = new Set();\r\n      const seenSlots = new Set();\r\n\r\n      timetables.forEach(timetable => {\r\n        const className = timetable.class || String(timetable.id).split(\"-\")[0] || \"\";\r\n        const sectionName = timetable.section || String(timetable.id).split(\"-\").slice(1).join(\"-\") || \"\";\r\n        const classLabel = sectionName ? `${className}-${sectionName}` : className;\r\n\r\n        Object.entries(timetable.schedule || {}).forEach(([day, daySlots]) => {\r\n          Object.entries(daySlots || {}).forEach(([period, slot]) => {\r\n            if (!slotBelongsToTeacher(slot, teacher)) return;\r\n            const commonTime = timetable.periodTimes?.[period] || {};\r\n            const uniqueSlotKey = `${timetableKey(timetable)}|${day}|${period}|${teacher.uid}`;\r\n            if (seenSlots.has(uniqueSlotKey)) return;\r\n            seenSlots.add(uniqueSlotKey);\r\n            if (!teacherSchedule[day]) teacherSchedule[day] = {};\r\n            if (!teacherSchedule[day][period]) teacherSchedule[day][period] = [];\r\n            teacherSchedule[day][period].push({\r\n              ...slot,\r\n              startTime: commonTime.startTime || slot.startTime || \"\",\r\n              endTime: commonTime.endTime || slot.endTime || \"\",\r\n              classLabel,\r\n              class: className,\r\n              section: sectionName\r\n            });\r\n            slotCount += 1;\r\n            if (classLabel) classSet.add(classLabel);\r\n          });\r\n        });\r\n      });\r\n\r\n      const card = document.getElementById(\"teacherViewCard\");\r\n      document.getElementById(\"teacherViewTitle\").textContent =\r\n        `${teacher.name} - Full Timetable`;\r\n      document.getElementById(\"teacherViewMeta\").textContent =\r\n        `Teacher ID: ${teacher.teacherId || teacher.uid} | ${slotCount} lecture${slotCount === 1 ? \"\" : \"s\"} | ${classSet.size} class${classSet.size === 1 ? \"\" : \"es\"}`;\r\n\r\n      document.getElementById(\"teacherTimetableView\").innerHTML = renderTeacherReadonlyTimetable(teacherSchedule);\r\n      card.classList.add(\"show\");\r\n      card.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\r\n    } catch (error) {\r\n      console.error(error);\r\n      toast(\"Failed to load teacher timetable\", \"error\");\r\n    }\r\n    showLoading(false);\r\n  };\r\n\r\n  function renderTeacherReadonlyTimetable(schedule = {}) {\r\n    const scheduleDays = days.filter(day => schedule[day]);\r\n    const allPeriods = sortPeriodKeys([...new Set(scheduleDays.flatMap(day => Object.keys(schedule[day] || {})))]);\r\n\r\n    if (!scheduleDays.length || !allPeriods.length) {\r\n      return `<div class=\"empty-state\" style=\"padding:2rem;\"><h3>No timetable found</h3><p>No periods are assigned to this teacher yet.</p></div>`;\r\n    }\r\n\r\n    let html = `<div class=\"table-wrapper\"><table>\r\n      <thead><tr>\r\n        <th>Period / Time</th>\r\n        ${days.map(day => `<th>${day}</th>`).join(\"\")}\r\n      </tr></thead><tbody>`;\r\n\r\n    allPeriods.forEach(period => {\r\n      html += `<tr><td><div class=\"period-cell\"><div class=\"period-num\">${escHtml(period)}</div></div></td>`;\r\n      days.forEach(day => {\r\n        const slots = schedule[day]?.[period] || [];\r\n        if (!slots.length) {\r\n          html += `<td><span style=\"color:var(--muted);font-size:0.8rem;\">—</span></td>`;\r\n          return;\r\n        }\r\n        html += `<td>${slots.map(slot => `\r\n          <div class=\"readonly-slot\">\r\n            <strong>${escHtml(slot.subject || \"Lecture\")}</strong>\r\n            <div>Class: ${escHtml(slot.classLabel || \"—\")}</div>\r\n            <div>Teacher ID: ${escHtml(getTeacherReadableId(slot))}</div>\r\n          </div>\r\n        `).join('<div style=\"height:8px\"></div>')}</td>`;\r\n      });\r\n      html += `</tr>`;\r\n    });\r\n\r\n    html += `</tbody></table></div>`;\r\n    return html;\r\n  }\r\n\r\n  function escHtml(s) {\r\n    return String(s).replace(/&/g,\"&amp;\").replace(/\"/g,\"&quot;\").replace(/</g,\"&lt;\").replace(/>/g,\"&gt;\");\r\n  }\r\n\r\n  // ── SAVE ──\r\n  renderTimetable = function renderTimetableFlipped() {\r\n    const container = document.getElementById(\"timetableContainer\");\r\n    normalizeTimetablePeriods();\r\n    const periods = getSortedPeriodKeys();\r\n    document.getElementById(\"statPeriods\").textContent = periods.length;\r\n\r\n    let html = `<div class=\"table-wrapper\"><table><thead><tr><th>Day</th>`;\r\n    html += periods.map(period => {\r\n      const periodTime = getPeriodTime(period);\r\n      const timeLabel = getTimeLabel(periodTime);\r\n      const pNum = period.replace(\"Period \", \"\");\r\n      return `<th><div class=\"period-cell\"><div class=\"period-num\">${escHtml(period)}</div><div class=\"period-time-display\" id=\"time-display-${period.replace(\" \", \"_\")}\">${escHtml(timeLabel)}</div><div class=\"period-time-controls\"><div class=\"field-label-small\"><span style=\"color:var(--gold)\">Start</span></div>${renderTime12Controls(period, \"startTime\", periodTime.startTime || \"\")}<div class=\"field-label-small\"><span style=\"color:var(--gold)\">End</span></div>${renderTime12Controls(period, \"endTime\", periodTime.endTime || \"\")}${periods.length > 1 ? `<button class=\"btn btn-danger period-remove\" onclick=\"removePeriod(${pNum})\">Remove</button>` : \"\"}</div></div></th>`;\r\n    }).join(\"\");\r\n    html += `</tr></thead><tbody>`;\r\n\r\n    days.forEach(day => {\r\n      html += `<tr><td><strong>${escHtml(day)}</strong></td>`;\r\n      periods.forEach(period => {\r\n        const slot = currentTimetable.schedule[day]?.[period] || {};\r\n        const slotKey = `${day}-${period.replace(/ /g, \"_\")}`;\r\n        const teacherUid = slot.teacherUid || slot.teacherId || \"\";\r\n        html += `<td><div class=\"slot-cell\">\r\n          <div class=\"field-label-small\">Subject</div>\r\n          <select class=\"slot-input subject-input\" onchange=\"onSlotSubjectChange('${day}','${period}',this)\">${subjectOptions(slot.subject || \"\")}</select>\r\n          <div class=\"field-label-small\" style=\"margin-top:2px\">Teacher</div>\r\n          <select class=\"slot-input teacher-select\" id=\"tsel-${slotKey}\" onchange=\"onSlotTeacherChange('${day}','${period}',this)\">${teacherSelectOptions(slot.subject || \"\", teacherUid, day, period)}</select>\r\n          <div class=\"teacher-id-badge\"><span id=\"tid-${slotKey}\">${escHtml(getTeacherReadableId(slot))}</span></div>\r\n        </div></td>`;\r\n      });\r\n      html += `</tr>`;\r\n    });\r\n\r\n    html += `</tbody></table></div>`;\r\n    container.innerHTML = html;\r\n  };\r\n\r\n  renderTeacherReadonlyTimetable = function renderTeacherReadonlyTimetableFlipped(schedule = {}) {\r\n    const scheduleDays = days.filter(day => schedule[day]);\r\n    const allPeriods = sortPeriodKeys([...new Set(scheduleDays.flatMap(day => Object.keys(schedule[day] || {})))]);\r\n    if (!scheduleDays.length || !allPeriods.length) return `<div class=\"empty-state\" style=\"padding:2rem;\"><h3>No timetable found</h3><p>No periods are assigned to this teacher yet.</p></div>`;\r\n    let html = `<div class=\"table-wrapper\"><table><thead><tr><th>Day</th>`;\r\n    allPeriods.forEach(period => {\r\n      const firstSlot = scheduleDays.flatMap(day => schedule[day]?.[period] || []).find(slot => getTimeLabel(slot)) || {};\r\n      const time = getTimeLabel(firstSlot);\r\n      html += `<th><strong>${escHtml(period)}</strong>${time ? `<div class=\"class-info\">${escHtml(time)}</div>` : \"\"}</th>`;\r\n    });\r\n    html += `</tr></thead><tbody>`;\r\n    scheduleDays.forEach(day => {\r\n      html += `<tr><td><strong>${escHtml(day)}</strong></td>`;\r\n      allPeriods.forEach(period => {\r\n        const slots = schedule[day]?.[period] || [];\r\n        html += slots.length ? `<td>${slots.map(slot => `<div class=\"readonly-slot\"><strong>${escHtml(slot.subject || \"Lecture\")}</strong><div>Class: ${escHtml(slot.classLabel || \"-\")}</div><div>Teacher ID: ${escHtml(getTeacherReadableId(slot))}</div></div>`).join('<div style=\"height:8px\"></div>')}</td>` : `<td><span style=\"color:var(--muted);font-size:0.8rem;\">-</span></td>`;\r\n      });\r\n      html += `</tr>`;\r\n    });\r\n    html += `</tbody></table></div>`;\r\n    return html;\r\n  };\r\n\r\n  window.saveTimetable = async function () {\r\n    if (!currentTimetable) { toast(\"Load a timetable first\", \"error\"); return; }\r\n    showLoading(true, \"Saving timetable...\");\r\n    try {\r\n      await nextPaint();\r\n      normalizeTimetablePeriods();\r\n      syncPeriodTimesToSlots();\r\n      await refreshTimetableCache(true);\r\n      if (!validateNoTeacherConflicts()) {\r\n        showLoading(false);\r\n        return;\r\n      }\r\n      const ref = doc(db, \"schools\", currentUser.uid, \"timetables\",\r\n        `${currentTimetable.class}-${currentTimetable.section}`);\r\n      await setDoc(ref, { ...currentTimetable, updatedAt: serverTimestamp() });\r\n      allTimetables = allTimetables.filter(timetable => (timetable.id || `${timetable.class || \"\"}-${timetable.section || \"\"}`) !== currentTimetableDocId());\r\n      allTimetables.push({ id: currentTimetableDocId(), ...currentTimetable });\r\n      allTimetables = dedupeTimetables(allTimetables);\r\n      toast(\"Timetable saved successfully!\");\r\n    } catch(e) {\r\n      console.error(e);\r\n      toast(\"Error saving timetable\", \"error\");\r\n    }\r\n    showLoading(false);\r\n  };\r\n\r\n  // ── AUTH ──\r\n  onAuthStateChanged(auth, async user => {\r\n    if (!user) { toast(\"Please login first\", \"error\"); return; }\r\n    currentUser = user;\r\n    showLoading(true, \"Preparing admin timetable...\");\r\n    await nextPaint();\r\n    await loadTeachers();\r\n    await loadSchoolSubjects();\r\n    await loadClasses();\r\n    showLoading(false);\r\n    refreshTimetableCache().catch(console.error);\r\n  });\r\n</script>\r\n<script type=\"module\" src=\"access-control.js\"></script>\r\n  <script src=\"schoolix-polish.js\" defer></script>\r\n  <script src=\"admin-shell.js?v=navbar-20260721\" defer></script>\r\n","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\nhtml.sx-page-loading,\nhtml.sx-page-loading body {\n  min-height: 100%;\n  background: #f8fafc !important;\n}\nhtml.sx-page-loading body::before,\nhtml.sx-page-loading body::after {\n  visibility: hidden !important;\n}\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\n  visibility: hidden !important;\n}\n.sx-page-loader {\n  position: fixed;\n  inset: 0;\n  z-index: 2147482500;\n  display: flex;\n  align-items: stretch;\n  justify-content: stretch;\n  background: #f8fafc;\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\n  overflow: hidden;\n}\n.sx-page-loader.is-hidden {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n}\n.sx-page-loader .dots-container {\n  position: fixed;\n  inset: 0;\n  display: block;\n  width: 100vw;\n  height: 100vh;\n  padding: 0;\n  margin: 0;\n  overflow: hidden;\n  background: #f8fafc;\n}\n.sx-page-loader .dots-container::before,\n.sx-page-loader .dots-container::after,\n.sx-page-loader .dot {\n  display: none !important;\n}\n"},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-erp.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"admin-shell.css?v=navbar-20260721"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 1600);\r\n}());\r\n"},{"attributes":{"type":"module"},"text":"\r\n  import { initializeApp }          from \"./firebase-compat.js\";\r\n  import { getAuth, onAuthStateChanged } from \"./firebase-compat.js\";\r\n  import {\r\n    getFirestore, collection, getDocs,\r\n    query, where, doc, getDoc, setDoc, serverTimestamp\r\n  } from \"./firebase-compat.js\";\r\n\r\n  // ── FIREBASE ──\r\n  const firebaseConfig = {\r\n    apiKey:            \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n    authDomain:        \"schoolix-48107.firebaseapp.com\",\r\n    projectId:         \"schoolix-48107\",\r\n    storageBucket:     \"schoolix-48107.firebasestorage.app\",\r\n    messagingSenderId: \"133937954491\",\r\n    appId:             \"1:133937954491:web:69d8064422617eb8c4339e\"\r\n  };\r\n  const app  = initializeApp(firebaseConfig);\r\n  const auth = getAuth(app);\r\n  const db   = getFirestore(app);\r\n\r\n  let currentUser      = null;\r\n  let teachers         = [];\r\n  let allStudents      = [];\r\n  let currentTimetable = null;\r\n  let currentClassSubjects = [];\r\n  let allTimetables = [];\r\n  let timetableCachePromise = null;\r\n  let timetableCacheAt = 0;\r\n  let loadClassesRun = 0;\r\n\r\n  const days = [\"Monday\",\"Tuesday\",\"Wednesday\",\"Thursday\",\"Friday\",\"Saturday\"];\r\n\r\n  // ── HELPERS ──\r\n  function showLoading(on, message = \"Loading data...\") {\r\n    const overlay = document.getElementById(\"loadingOverlay\");\r\n    const text = document.getElementById(\"loadingText\");\r\n    if (text) text.textContent = message;\r\n    overlay.classList.toggle(\"show\", on);\r\n  }\r\n  function nextPaint() {\r\n    return new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));\r\n  }\r\n  function toast(msg, type = \"success\") {\r\n    const t    = document.getElementById(\"toast\");\r\n    const icon = document.getElementById(\"toastIcon\");\r\n    document.getElementById(\"toastMsg\").textContent = msg;\r\n    t.className = `toast ${type} show`;\r\n    icon.innerHTML = type === \"success\"\r\n      ? `<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>`\r\n      : `<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"16\"/><line x1=\"12\" y1=\"20\" x2=\"12.01\" y2=\"20\"/></svg>`;\r\n    clearTimeout(t._timer);\r\n    t._timer = setTimeout(() => t.classList.remove(\"show\"), 3000);\r\n  }\r\n\r\n  // ── LOAD CLASSES ──\r\n  function cleanText(value) {\r\n    return String(value || \"\").replace(/\\s+/g, \" \").trim();\r\n  }\r\n\r\n  function canonicalClass(value) {\r\n    return cleanText(value);\r\n  }\r\n\r\n  function canonicalSection(value) {\r\n    return cleanText(value).toUpperCase();\r\n  }\r\n\r\n  function normalizeIdentity(value) {\r\n    return cleanText(value).toLowerCase();\r\n  }\r\n\r\n  function teacherIdentityKey(teacher = {}) {\r\n    const legacyUid = normalizeIdentity(teacher.legacyUid || teacher.firebaseUid);\r\n    if (legacyUid) return `uid:${legacyUid}`;\r\n    const teacherId = normalizeIdentity(teacher.teacherId);\r\n    if (teacherId) return `teacherId:${teacherId}`;\r\n    const email = normalizeIdentity(teacher.email || teacher.authEmail);\r\n    if (email) return `email:${email}`;\r\n    return `doc:${normalizeIdentity(teacher.uid || teacher.docId)}`;\r\n  }\r\n\r\n  function teacherScore(teacher = {}) {\r\n    const docId = cleanText(teacher.docId || teacher.uid);\r\n    const legacyUid = cleanText(teacher.legacyUid || teacher.firebaseUid);\r\n    const isMirror = Boolean(legacyUid && docId && legacyUid !== docId);\r\n    return (isMirror ? 0 : 100)\r\n      + (teacher.removedFromPanel === true || teacher.panelStatus === \"removed\" || teacher.active === false ? 0 : 10)\r\n      + (teacher.teacherId ? 4 : 0)\r\n      + (teacher.name ? 2 : 0);\r\n  }\r\n\r\n  function dedupeTeachers(list = []) {\r\n    const byIdentity = new Map();\r\n    list.forEach(teacher => {\r\n      const key = teacherIdentityKey(teacher);\r\n      const current = byIdentity.get(key);\r\n      if (!current || teacherScore(teacher) > teacherScore(current)) {\r\n        byIdentity.set(key, teacher);\r\n      }\r\n    });\r\n    return [...byIdentity.values()];\r\n  }\r\n\r\n  function timetableKey(timetable = {}) {\r\n    const className = canonicalClass(timetable.class || String(timetable.id || \"\").split(\"-\")[0]);\r\n    const sectionName = canonicalSection(timetable.section || String(timetable.id || \"\").split(\"-\").slice(1).join(\"-\"));\r\n    if (className || sectionName) return `${className}|${sectionName}`;\r\n    return cleanText(timetable.id);\r\n  }\r\n\r\n  function dedupeTimetables(list = []) {\r\n    const byClassSection = new Map();\r\n    list.forEach(timetable => {\r\n      const key = timetableKey(timetable);\r\n      if (!key) return;\r\n      const current = byClassSection.get(key);\r\n      if (!current || String(timetable.updatedAt || \"\").localeCompare(String(current.updatedAt || \"\")) >= 0) {\r\n        byClassSection.set(key, timetable);\r\n      }\r\n    });\r\n    return [...byClassSection.values()];\r\n  }\r\n\r\n  function createSelectOption(value, label = value) {\r\n    const option = document.createElement(\"option\");\r\n    option.value = value;\r\n    option.textContent = label;\r\n    return option;\r\n  }\r\n\r\n  function replaceSelectOptions(select, placeholder, values = [], selectedValue = \"\") {\r\n    if (!select) return;\r\n    const options = [\r\n      createSelectOption(\"\", placeholder),\r\n      ...values.map(value => createSelectOption(value))\r\n    ];\r\n    select.replaceChildren(...options);\r\n    if (selectedValue && values.some(value => String(value) === String(selectedValue))) {\r\n      select.value = selectedValue;\r\n    }\r\n  }\r\n\r\n  async function loadClasses() {\r\n    const runId = ++loadClassesRun;\r\n    const classSelect   = document.getElementById(\"classSelect\");\r\n    const sectionSelect = document.getElementById(\"sectionSelect\");\r\n    if (!classSelect || !sectionSelect) return;\r\n    const previousClass = classSelect.value;\r\n    const previousSection = sectionSelect.value;\r\n\r\n    const snap = await getDocs(collection(db, \"schools\", currentUser.uid, \"students\"));\r\n    const nextStudents = [];\r\n    snap.forEach(d => {\r\n      const data = d.data();\r\n      const className = canonicalClass(data.class);\r\n      const sectionName = canonicalSection(data.section);\r\n      if (className && sectionName)\r\n        nextStudents.push({ class: className, section: sectionName });\r\n    });\r\n    const seenPlacements = new Set();\r\n    const uniquePlacements = nextStudents.filter(student => {\r\n      const key = `${student.class}|${student.section}`;\r\n      if (seenPlacements.has(key)) return false;\r\n      seenPlacements.add(key);\r\n      return true;\r\n    });\r\n    if (runId !== loadClassesRun) return;\r\n    allStudents = uniquePlacements;\r\n\r\n    const uniqueClasses = [...new Set(allStudents.map(s => s.class))];\r\n    uniqueClasses.sort((a, b) => (parseInt(a) || 0) - (parseInt(b) || 0));\r\n\r\n    const renderSections = (selectedSection = \"\") => {\r\n      const sel = classSelect.value;\r\n      const sections = [...new Set(allStudents.filter(s => s.class === sel).map(s => s.section))];\r\n      sections.sort();\r\n      replaceSelectOptions(sectionSelect, \"Select Section\", sections, selectedSection);\r\n    };\r\n\r\n    replaceSelectOptions(classSelect, \"Select Class\", uniqueClasses, previousClass);\r\n    renderSections(classSelect.value === previousClass ? previousSection : \"\");\r\n\r\n    classSelect.onchange = () => {\r\n      renderSections(\"\");\r\n    };\r\n  }\r\n\r\n  // ── LOAD TEACHERS ──\r\n  async function loadTeachers() {\r\n    const nextTeachers = [];\r\n    const q    = query(collection(db, \"users\"), where(\"role\",\"==\",\"teacher\"), where(\"adminId\",\"==\",currentUser.uid));\r\n    const snap = await getDocs(q);\r\n    snap.forEach(d => {\r\n      const data = d.data() || {};\r\n      const rawSubjects = data.subjects || (data.subject ? [data.subject] : []);\r\n      const subjectsList = Array.isArray(rawSubjects) ? rawSubjects : [rawSubjects];\r\n      nextTeachers.push({\r\n        uid: d.id,\r\n        docId: d.id,\r\n        teacherId: data.teacherId || \"\",\r\n        email: cleanText(data.email || \"\"),\r\n        authEmail: cleanText(data.authEmail || \"\"),\r\n        name: cleanText(data.name || \"Teacher\"),\r\n        subjects: subjectsList.map(s => String(s).trim()).filter(Boolean),\r\n        legacyUid: data.legacyUid || \"\",\r\n        firebaseUid: data.firebaseUid || \"\",\r\n        panelStatus: data.panelStatus || \"\",\r\n        removedFromPanel: data.removedFromPanel === true,\r\n        active: data.active !== false\r\n      });\r\n    });\r\n    teachers = dedupeTeachers(nextTeachers)\r\n      .filter(teacher => teacher.removedFromPanel !== true && teacher.panelStatus !== \"removed\" && teacher.active !== false);\r\n    populateTeacherViewSelect();\r\n  }\r\n\r\n  function populateTeacherViewSelect() {\r\n    const sel = document.getElementById(\"teacherViewSelect\");\r\n    if (!sel) return;\r\n    sel.innerHTML = `<option value=\"\">Select Teacher</option>`;\r\n    teachers\r\n      .slice()\r\n      .sort((a, b) => String(a.name || \"\").localeCompare(String(b.name || \"\")))\r\n      .forEach(teacher => {\r\n        const opt = document.createElement(\"option\");\r\n        opt.value = teacher.uid;\r\n        opt.textContent = `${teacher.name} (${teacher.teacherId || teacher.uid})`;\r\n        sel.appendChild(opt);\r\n      });\r\n  }\r\n\r\n  function findTeacherBySlot(slot = {}) {\r\n    const candidates = [slot.teacherUid, slot.teacherId, slot.teacher, slot.teacherEmail]\r\n      .map(v => String(v || \"\").trim().toLowerCase())\r\n      .filter(Boolean);\r\n    return teachers.find(t => {\r\n      const ids = [t.uid, t.teacherId, t.email, t.name]\r\n        .map(v => String(v || \"\").trim().toLowerCase())\r\n        .filter(Boolean);\r\n      return candidates.some(candidate => ids.includes(candidate));\r\n    }) || null;\r\n  }\r\n\r\n  function hasTeacherReference(slot = {}) {\r\n    return [slot.teacherUid, slot.teacherId, slot.teacherName, slot.teacherEmail, slot.teacher]\r\n      .some(value => cleanText(value));\r\n  }\r\n\r\n  function clearTeacherReference(slot = {}) {\r\n    slot.teacherUid = \"\";\r\n    slot.teacherId = \"\";\r\n    slot.teacherName = \"\";\r\n    slot.teacherEmail = \"\";\r\n    if (\"teacher\" in slot) slot.teacher = \"\";\r\n    return slot;\r\n  }\r\n\r\n  function clearInactiveTeacherSlots(schedule = currentTimetable?.schedule) {\r\n    if (!schedule) return;\r\n    Object.values(schedule || {}).forEach(daySlots => {\r\n      Object.values(daySlots || {}).forEach(slot => {\r\n        if (hasTeacherReference(slot) && !findTeacherBySlot(slot)) clearTeacherReference(slot);\r\n      });\r\n    });\r\n  }\r\n\r\n  function getTeacherReadableId(slot = {}) {\r\n    const teacher = findTeacherBySlot(slot);\r\n    return teacher?.teacherId || slot.teacherReadableId || slot.teacherId || slot.teacherUid || \"—\";\r\n  }\r\n\r\n  function slotBelongsToTeacher(slot = {}, teacher = {}) {\r\n    const slotIds = [slot.teacherUid, slot.teacherId, slot.teacher, slot.teacherEmail, slot.teacherName]\r\n      .map(v => String(v || \"\").trim().toLowerCase())\r\n      .filter(Boolean);\r\n    const teacherIds = [teacher.uid, teacher.teacherId, teacher.email, teacher.name]\r\n      .map(v => String(v || \"\").trim().toLowerCase())\r\n      .filter(Boolean);\r\n    return slotIds.some(id => teacherIds.includes(id));\r\n  }\r\n\r\n  // ── EMPTY SCHEDULE ──\r\n  function createEmptySchedule() {\r\n    const schedule = {};\r\n    days.forEach(day => {\r\n      schedule[day] = {};\r\n      for (let i = 1; i <= 7; i++) {\r\n        schedule[day][`Period ${i}`] = { subject: \"\", teacherUid: \"\", teacherId: \"\", teacherName: \"\" };\r\n      }\r\n    });\r\n    return schedule;\r\n  }\r\n\r\n  function createEmptyPeriodTimes(count = 7) {\r\n    const periodTimes = {};\r\n    for (let i = 1; i <= count; i++) {\r\n      periodTimes[`Period ${i}`] = { startTime: \"\", endTime: \"\" };\r\n    }\r\n    return periodTimes;\r\n  }\r\n\r\n  function getSortedPeriodKeys(schedule = currentTimetable?.schedule) {\r\n    return Object.keys(schedule?.Monday || {})\r\n      .sort((a,b) => parseInt(a.replace(\"Period \",\"\")) - parseInt(b.replace(\"Period \",\"\")));\r\n  }\r\n\r\n  function normalizeTimetablePeriods() {\r\n    if (!currentTimetable?.schedule) return;\r\n    const orderedPeriods = getSortedPeriodKeys();\r\n    const normalized = {};\r\n    const normalizedTimes = {};\r\n    days.forEach(day => { normalized[day] = {}; });\r\n\r\n    orderedPeriods.forEach((period, index) => {\r\n      const nextKey = `Period ${index + 1}`;\r\n      const savedTime = currentTimetable.periodTimes?.[period] || {};\r\n      const legacyTimeSlot = days\r\n        .map(day => currentTimetable.schedule[day]?.[period])\r\n        .find(slot => slot?.startTime || slot?.endTime) || {};\r\n      normalizedTimes[nextKey] = {\r\n        startTime: savedTime.startTime || legacyTimeSlot.startTime || \"\",\r\n        endTime: savedTime.endTime || legacyTimeSlot.endTime || \"\"\r\n      };\r\n      days.forEach(day => {\r\n        const slot = currentTimetable.schedule[day]?.[period] || {};\r\n        const matchedTeacher = findTeacherBySlot(slot);\r\n        const teacherFields = matchedTeacher ? {\r\n          teacherUid: slot.teacherUid || matchedTeacher.uid || \"\",\r\n          teacherId: matchedTeacher.teacherId || slot.teacherId || \"\",\r\n          teacherName: slot.teacherName || matchedTeacher.name || \"\",\r\n          teacherEmail: slot.teacherEmail || matchedTeacher.email || \"\"\r\n        } : {\r\n          teacherUid: \"\",\r\n          teacherId: \"\",\r\n          teacherName: \"\",\r\n          teacherEmail: \"\"\r\n        };\r\n        normalized[day][nextKey] = {\r\n          subject: slot.subject || \"\",\r\n          ...teacherFields\r\n        };\r\n      });\r\n    });\r\n\r\n    currentTimetable.schedule = normalized;\r\n    currentTimetable.periodTimes = normalizedTimes;\r\n    syncPeriodTimesToSlots();\r\n  }\r\n\r\n  function getPeriodTime(period) {\r\n    currentTimetable.periodTimes = currentTimetable.periodTimes || {};\r\n    currentTimetable.periodTimes[period] = currentTimetable.periodTimes[period] || { startTime: \"\", endTime: \"\" };\r\n    return currentTimetable.periodTimes[period];\r\n  }\r\n\r\n  function syncPeriodTimesToSlots() {\r\n    if (!currentTimetable?.schedule) return;\r\n    getSortedPeriodKeys().forEach(period => {\r\n      const time = getPeriodTime(period);\r\n      days.forEach(day => {\r\n        currentTimetable.schedule[day][period] = currentTimetable.schedule[day][period] || {};\r\n        currentTimetable.schedule[day][period].startTime = time.startTime || \"\";\r\n        currentTimetable.schedule[day][period].endTime = time.endTime || \"\";\r\n      });\r\n    });\r\n  }\r\n\r\n  // ── LOAD TIMETABLE ──\r\n  function extractPeriodTimes(timetable = {}) {\r\n    const schedule = timetable.schedule || {};\r\n    const sourcePeriods = sortPeriodKeys([\r\n      ...new Set([\r\n        ...Object.keys(timetable.periodTimes || {}),\r\n        ...Object.keys(schedule.Monday || {})\r\n      ])\r\n    ]);\r\n    const extracted = {};\r\n    sourcePeriods.forEach((period, index) => {\r\n      const targetPeriod = `Period ${index + 1}`;\r\n      const savedTime = timetable.periodTimes?.[period] || {};\r\n      const legacyTimeSlot = days\r\n        .map(day => schedule[day]?.[period])\r\n        .find(slot => slot?.startTime || slot?.endTime) || {};\r\n      extracted[targetPeriod] = {\r\n        startTime: savedTime.startTime || legacyTimeSlot.startTime || \"\",\r\n        endTime: savedTime.endTime || legacyTimeSlot.endTime || \"\"\r\n      };\r\n    });\r\n    return extracted;\r\n  }\r\n\r\n  function normalizeSubjectName(value) {\r\n    return String(value || \"\").replace(/\\s+/g, \" \").trim();\r\n  }\r\n\r\n  function mergeSubjects(...lists) {\r\n    const seen = new Set();\r\n    const subjects = [];\r\n    lists.flat().forEach(value => {\r\n      const name = normalizeSubjectName(typeof value === \"string\" ? value : value?.name);\r\n      const key = name.toLowerCase();\r\n      if (!name || seen.has(key)) return;\r\n      seen.add(key);\r\n      subjects.push(name);\r\n    });\r\n    return subjects.sort((a, b) => a.localeCompare(b));\r\n  }\r\n\r\n  function collectSubjectsFromSchedule(schedule = currentTimetable?.schedule) {\r\n    const subjects = [];\r\n    Object.values(schedule || {}).forEach(daySlots => {\r\n      Object.values(daySlots || {}).forEach(slot => subjects.push(slot?.subject || \"\"));\r\n    });\r\n    return mergeSubjects(subjects);\r\n  }\r\n\r\n  function classSubjectDocId(className = currentTimetable?.class) {\r\n    return `timetable-${String(className || \"\").replace(/[^a-zA-Z0-9_-]/g, \"_\")}`;\r\n  }\r\n\r\n  function classSubjectsRef(className = currentTimetable?.class) {\r\n    return doc(db, \"schools\", currentUser.uid, \"subjects\", classSubjectDocId(className));\r\n  }\r\n\r\n  async function refreshTimetableCache(force = false) {\r\n    if (!currentUser) return allTimetables;\r\n    const cacheIsFresh = allTimetables.length && (Date.now() - timetableCacheAt < 60000);\r\n    if (!force && cacheIsFresh) return allTimetables;\r\n    if (!force && timetableCachePromise) return timetableCachePromise;\r\n    timetableCachePromise = getDocs(collection(db, \"schools\", currentUser.uid, \"timetables\"))\r\n      .then(snapshot => {\r\n        allTimetables = dedupeTimetables(snapshot.docs.map(item => ({ id: item.id, ...(item.data() || {}) })));\r\n        timetableCacheAt = Date.now();\r\n        return allTimetables;\r\n      })\r\n      .finally(() => { timetableCachePromise = null; });\r\n    return timetableCachePromise;\r\n  }\r\n\r\n  let schoolSubjects = [];\r\n\r\n  async function loadSchoolSubjects() {\r\n    if (!currentUser) return [];\r\n    try {\r\n      const snap = await getDocs(collection(db, \"schools\", currentUser.uid, \"subjects\"));\r\n      const list = [];\r\n      snap.forEach(d => {\r\n        const data = d.data() || {};\r\n        const name = normalizeSubjectName(data.name || \"\");\r\n        if (name) list.push(name);\r\n      });\r\n      schoolSubjects = mergeSubjects(list);\r\n    } catch (e) {\r\n      console.warn(\"Failed to load school subjects from Firestore:\", e);\r\n    }\r\n    return schoolSubjects;\r\n  }\r\n\r\n  function subjectOptions(selected = \"\") {\r\n    const selectedName = normalizeSubjectName(selected);\r\n    const subjects = mergeSubjects(schoolSubjects, selectedName ? [selectedName] : []);\r\n    const options = [`<option value=\"\">Select subject</option>`];\r\n    subjects.forEach(subject => {\r\n      const isSelected = subject.toLowerCase() === selectedName.toLowerCase() ? \" selected\" : \"\";\r\n      options.push(`<option value=\"${escHtml(subject)}\"${isSelected}>${escHtml(subject)}</option>`);\r\n    });\r\n    if (!subjects.length) options.push(`<option value=\"\" disabled>No school subjects found</option>`);\r\n    return options.join(\"\");\r\n  }\r\n\r\n  function getTeachersForSubject(subject) {\r\n    if (!subject) return teachers;\r\n    const target = String(subject).trim().toLowerCase();\r\n    return teachers.filter(t => {\r\n      const subList = Array.isArray(t.subjects) ? t.subjects : (t.subject ? [t.subject] : []);\r\n      return subList.some(s => String(s).trim().toLowerCase() === target);\r\n    });\r\n  }\r\n\r\n  function teacherSelectOptions(subject = \"\", selectedTeacherUid = \"\", day = \"\", period = \"\") {\r\n    const cleanSubj = String(subject || \"\").trim();\r\n    const matching = getTeachersForSubject(cleanSubj);\r\n    const options = [`<option value=\"\">Select teacher</option>`];\r\n    const isTeacherSelected = (t) => {\r\n      if (!selectedTeacherUid) return false;\r\n      const target = String(selectedTeacherUid).toLowerCase();\r\n      return (t.uid && t.uid.toLowerCase() === target) ||\r\n             (t.teacherId && t.teacherId.toLowerCase() === target) ||\r\n             (t.name && t.name.toLowerCase() === target);\r\n    };\r\n\r\n    if (cleanSubj && matching.length > 0) {\r\n      matching.forEach(t => {\r\n        const isSelected = isTeacherSelected(t);\r\n        const conflict = (day && period) ? findTeacherConflict(t, day, period) : null;\r\n        options.push(`<option value=\"${t.uid}\"${isSelected ? \" selected\" : \"\"}>${escHtml(t.name)} (${escHtml(t.teacherId || t.uid)})${conflict ? \" [Busy]\" : \"\"}</option>`);\r\n      });\r\n      const otherTeachers = teachers.filter(t => !matching.some(m => m.uid === t.uid));\r\n      if (otherTeachers.length > 0) {\r\n        options.push(`<optgroup label=\"Other Teachers\">`);\r\n        otherTeachers.forEach(t => {\r\n          const isSelected = isTeacherSelected(t);\r\n          const conflict = (day && period) ? findTeacherConflict(t, day, period) : null;\r\n          options.push(`<option value=\"${t.uid}\"${isSelected ? \" selected\" : \"\"}>${escHtml(t.name)} (${escHtml(t.teacherId || t.uid)})${conflict ? \" [Busy]\" : \"\"}</option>`);\r\n        });\r\n        options.push(`</optgroup>`);\r\n      }\r\n    } else if (cleanSubj && matching.length === 0) {\r\n      options.push(`<option value=\"\" disabled>-- No teacher assigned for \"${escHtml(cleanSubj)}\" --</option>`);\r\n      if (teachers.length > 0) {\r\n        options.push(`<optgroup label=\"All Teachers\">`);\r\n        teachers.forEach(t => {\r\n          const isSelected = isTeacherSelected(t);\r\n          const conflict = (day && period) ? findTeacherConflict(t, day, period) : null;\r\n          options.push(`<option value=\"${t.uid}\"${isSelected ? \" selected\" : \"\"}>${escHtml(t.name)} (${escHtml(t.teacherId || t.uid)})${conflict ? \" [Busy]\" : \"\"}</option>`);\r\n        });\r\n        options.push(`</optgroup>`);\r\n      }\r\n    } else {\r\n      teachers.forEach(t => {\r\n        const isSelected = isTeacherSelected(t);\r\n        const conflict = (day && period) ? findTeacherConflict(t, day, period) : null;\r\n        options.push(`<option value=\"${t.uid}\"${isSelected ? \" selected\" : \"\"}>${escHtml(t.name)} (${escHtml(t.teacherId || t.uid)})${conflict ? \" [Busy]\" : \"\"}</option>`);\r\n      });\r\n    }\r\n    return options.join(\"\");\r\n  }\r\n\r\n  window.onSlotSubjectChange = function (day, period, select) {\r\n    const subject = select.value || \"\";\r\n    updateSlot(day, period, \"subject\", subject);\r\n    const slotKey = `${day}-${period.replace(/ /g, \"_\")}`;\r\n    const teacherSel = document.getElementById(`tsel-${slotKey}`);\r\n    if (teacherSel) {\r\n      const currentSlot = currentTimetable.schedule?.[day]?.[period] || {};\r\n      const currentTeacherUid = currentSlot.teacherUid || currentSlot.teacherId || currentSlot.teacherName || \"\";\r\n      teacherSel.innerHTML = teacherSelectOptions(subject, currentTeacherUid, day, period);\r\n      \r\n      const matching = getTeachersForSubject(subject);\r\n      const stillMatches = currentTeacherUid && matching.some(t => t.uid === currentTeacherUid || t.teacherId === currentTeacherUid || t.name === currentTeacherUid);\r\n      if (!stillMatches && currentTeacherUid && subject) {\r\n        updateSlot(day, period, \"teacherUid\", \"\");\r\n        updateSlot(day, period, \"teacherId\", \"\");\r\n        updateSlot(day, period, \"teacherName\", \"\");\r\n        updateSlot(day, period, \"teacherEmail\", \"\");\r\n        teacherSel.value = \"\";\r\n        const badge = document.getElementById(`tid-${slotKey}`);\r\n        if (badge) badge.textContent = \"—\";\r\n      }\r\n    }\r\n  };\r\n\r\n  window.onSlotTeacherChange = function (day, period, select) {\r\n    const teacherUid = select.value;\r\n    const slotKey = `${day}-${period.replace(/ /g, \"_\")}`;\r\n    if (!teacherUid) {\r\n      updateSlot(day, period, \"teacherUid\", \"\");\r\n      updateSlot(day, period, \"teacherId\", \"\");\r\n      updateSlot(day, period, \"teacherName\", \"\");\r\n      updateSlot(day, period, \"teacherEmail\", \"\");\r\n      const badge = document.getElementById(`tid-${slotKey}`);\r\n      if (badge) badge.textContent = \"—\";\r\n      return;\r\n    }\r\n    const teacher = teachers.find(t => t.uid === teacherUid);\r\n    if (!teacher) return;\r\n    const conflict = findTeacherConflict(teacher, day, period);\r\n    if (conflict) {\r\n      toast(conflictMessage(teacher, conflict, day, period), \"error\");\r\n      select.value = currentTimetable.schedule?.[day]?.[period]?.teacherUid || \"\";\r\n      return;\r\n    }\r\n    updateSlot(day, period, \"teacherUid\", teacher.uid);\r\n    updateSlot(day, period, \"teacherId\", teacher.teacherId || teacher.uid);\r\n    updateSlot(day, period, \"teacherName\", teacher.name);\r\n    updateSlot(day, period, \"teacherEmail\", teacher.email || \"\");\r\n    const badge = document.getElementById(`tid-${slotKey}`);\r\n    if (badge) badge.textContent = teacher.teacherId || teacher.uid;\r\n  };\r\n\r\n  function getClassOptions() {\r\n    return [...new Set(allStudents.map(student => student.class).filter(Boolean))]\r\n      .sort((a, b) => (parseInt(a, 10) || 0) - (parseInt(b, 10) || 0) || String(a).localeCompare(String(b)));\r\n  }\r\n\r\n  function getSectionOptions(className) {\r\n    return [...new Set(allStudents\r\n      .filter(student => String(student.class) === String(className))\r\n      .map(student => student.section)\r\n      .filter(Boolean))]\r\n      .sort((a, b) => String(a).localeCompare(String(b)));\r\n  }\r\n\r\n  window.populateSyncSectionSelect = function () {\r\n    const className = document.getElementById(\"syncClassSelect\")?.value || \"\";\r\n    const sectionSelect = document.getElementById(\"syncSectionSelect\");\r\n    if (!sectionSelect) return;\r\n    sectionSelect.innerHTML = `<option value=\"\">Select Section</option>`;\r\n    getSectionOptions(className).forEach(section => {\r\n      const option = document.createElement(\"option\");\r\n      option.value = option.textContent = section;\r\n      sectionSelect.appendChild(option);\r\n    });\r\n  };\r\n\r\n  window.openSyncTimeModal = function () {\r\n    if (!currentTimetable) { toast(\"Load a timetable first\", \"error\"); return; }\r\n    const classSelect = document.getElementById(\"syncClassSelect\");\r\n    const meta = document.getElementById(\"syncTimeModalMeta\");\r\n    if (meta) meta.textContent = `Copy timings into Class ${currentTimetable.class}-${currentTimetable.section}`;\r\n    classSelect.innerHTML = `<option value=\"\">Select Class</option>`;\r\n    getClassOptions().forEach(className => {\r\n      const option = document.createElement(\"option\");\r\n      option.value = option.textContent = className;\r\n      classSelect.appendChild(option);\r\n    });\r\n    classSelect.value = currentTimetable.class || \"\";\r\n    populateSyncSectionSelect();\r\n    document.getElementById(\"syncSectionSelect\").value = currentTimetable.section || \"\";\r\n    const modal = document.getElementById(\"syncTimeModal\");\r\n    modal.classList.add(\"show\");\r\n    modal.setAttribute(\"aria-hidden\", \"false\");\r\n  };\r\n\r\n  window.closeSyncTimeModal = function () {\r\n    const modal = document.getElementById(\"syncTimeModal\");\r\n    modal.classList.remove(\"show\");\r\n    modal.setAttribute(\"aria-hidden\", \"true\");\r\n  };\r\n\r\n  window.syncTimeFromSelectedTimetable = async function () {\r\n    if (!currentTimetable) { toast(\"Load a timetable first\", \"error\"); return; }\r\n    const sourceClass = document.getElementById(\"syncClassSelect\")?.value || \"\";\r\n    const sourceSection = document.getElementById(\"syncSectionSelect\")?.value || \"\";\r\n    if (!sourceClass || !sourceSection) { toast(\"Select source class and section\", \"error\"); return; }\r\n    showLoading(true, \"Syncing period times...\");\r\n    try {\r\n      await nextPaint();\r\n      const sourceRef = doc(db, \"schools\", currentUser.uid, \"timetables\", `${sourceClass}-${sourceSection}`);\r\n      const sourceSnap = await getDoc(sourceRef);\r\n      if (!sourceSnap.exists()) {\r\n        toast(\"Selected timetable not found\", \"error\");\r\n        showLoading(false);\r\n        return;\r\n      }\r\n      const sourceTimes = extractPeriodTimes(sourceSnap.data() || {});\r\n      const currentPeriods = getSortedPeriodKeys();\r\n      let synced = 0;\r\n      currentTimetable.periodTimes = currentTimetable.periodTimes || {};\r\n      currentPeriods.forEach(period => {\r\n        const sourceTime = sourceTimes[period];\r\n        if (!sourceTime || (!sourceTime.startTime && !sourceTime.endTime)) return;\r\n        currentTimetable.periodTimes[period] = {\r\n          startTime: sourceTime.startTime || \"\",\r\n          endTime: sourceTime.endTime || \"\"\r\n        };\r\n        synced += 1;\r\n      });\r\n      syncPeriodTimesToSlots();\r\n      renderTimetable();\r\n      closeSyncTimeModal();\r\n      toast(synced ? `Synced ${synced} period time${synced === 1 ? \"\" : \"s\"}` : \"No period times found to sync\", synced ? \"success\" : \"error\");\r\n    } catch(e) {\r\n      console.error(e);\r\n      toast(\"Error syncing period times\", \"error\");\r\n    }\r\n    showLoading(false);\r\n  };\r\n\r\n  function clearSubjectFromSchedule(subject) {\r\n    const target = normalizeSubjectName(subject).toLowerCase();\r\n    if (!target || !currentTimetable?.schedule) return;\r\n    Object.values(currentTimetable.schedule).forEach(daySlots => {\r\n      Object.values(daySlots || {}).forEach(slot => {\r\n        if (normalizeSubjectName(slot?.subject).toLowerCase() === target) slot.subject = \"\";\r\n      });\r\n    });\r\n  }\r\n\r\n  function clearSubjectsNotInClassList() {\r\n    const allowed = new Set(currentClassSubjects.map(subject => subject.toLowerCase()));\r\n    if (!currentTimetable?.schedule) return;\r\n    Object.values(currentTimetable.schedule).forEach(daySlots => {\r\n      Object.values(daySlots || {}).forEach(slot => {\r\n        const subject = normalizeSubjectName(slot?.subject);\r\n        if (subject && !allowed.has(subject.toLowerCase())) slot.subject = \"\";\r\n      });\r\n    });\r\n  }\r\n\r\n  function currentTimetableDocId() {\r\n    if (!currentTimetable) return \"\";\r\n    return `${currentTimetable.class}-${currentTimetable.section}`;\r\n  }\r\n\r\n  function sameTeacher(teacher = {}, slot = {}) {\r\n    const teacherIds = [teacher.uid, teacher.teacherId, teacher.email, teacher.name]\r\n      .map(value => String(value || \"\").trim().toLowerCase())\r\n      .filter(Boolean);\r\n    const slotIds = [slot.teacherUid, slot.teacherId, slot.teacher, slot.teacherEmail, slot.teacherName]\r\n      .map(value => String(value || \"\").trim().toLowerCase())\r\n      .filter(Boolean);\r\n    return teacherIds.some(id => slotIds.includes(id));\r\n  }\r\n\r\n  function findTeacherConflict(teacher, day, period) {\r\n    const currentId = currentTimetableDocId();\r\n    return allTimetables.find(timetable => {\r\n      const timetableId = timetable.id || `${timetable.class || \"\"}-${timetable.section || \"\"}`;\r\n      if (timetableId === currentId) return false;\r\n      const slot = timetable.schedule?.[day]?.[period];\r\n      return slot && sameTeacher(teacher, slot);\r\n    }) || null;\r\n  }\r\n\r\n  function conflictMessage(teacher, conflict, day, period) {\r\n    const classLabel = [conflict?.class, conflict?.section].filter(Boolean).join(\" \");\r\n    return `${teacher.name} already has ${period} on ${day}${classLabel ? ` in Class ${classLabel}` : \"\"}.`;\r\n  }\r\n\r\n  function validateNoTeacherConflicts() {\r\n    if (!currentTimetable?.schedule) return true;\r\n    for (const day of days) {\r\n      const slots = currentTimetable.schedule[day] || {};\r\n      for (const period of Object.keys(slots)) {\r\n        const slot = slots[period] || {};\r\n        const teacher = findTeacherBySlot(slot);\r\n        if (!teacher) continue;\r\n        const conflict = findTeacherConflict(teacher, day, period);\r\n        if (conflict) {\r\n          toast(conflictMessage(teacher, conflict, day, period), \"error\");\r\n          return false;\r\n        }\r\n      }\r\n    }\r\n    return true;\r\n  }\r\n\r\n  window.addClassSubject = function () {\r\n    if (!currentTimetable) { toast(\"Load a timetable first\", \"error\"); return; }\r\n    const input = document.getElementById(\"subjectNameInput\");\r\n    const subject = normalizeSubjectName(input?.value || \"\");\r\n    if (!subject) { toast(\"Enter subject name\", \"error\"); return; }\r\n    currentClassSubjects = mergeSubjects(currentClassSubjects, [subject]);\r\n    currentTimetable.classSubjects = currentClassSubjects;\r\n    if (input) input.value = \"\";\r\n    renderSubjectsModal();\r\n    renderTimetable();\r\n  };\r\n\r\n  window.deleteClassSubject = function (index) {\r\n    const subject = currentClassSubjects[index];\r\n    if (!subject) return;\r\n    currentClassSubjects = currentClassSubjects.filter((_, i) => i !== index);\r\n    clearSubjectFromSchedule(subject);\r\n    currentTimetable.classSubjects = currentClassSubjects;\r\n    renderSubjectsModal();\r\n    renderTimetable();\r\n  };\r\n\r\n  window.saveClassSubjects = async function () {\r\n    if (!currentTimetable) { toast(\"Load a timetable first\", \"error\"); return; }\r\n    showLoading(true, \"Saving subjects...\");\r\n    try {\r\n      await nextPaint();\r\n      currentClassSubjects = mergeSubjects(currentClassSubjects);\r\n      currentTimetable.classSubjects = currentClassSubjects;\r\n      await setDoc(classSubjectsRef(), {\r\n        type: \"timetableClassSubjects\",\r\n        className: currentTimetable.class,\r\n        subjects: currentClassSubjects,\r\n        updatedAt: serverTimestamp()\r\n      });\r\n      const ref = doc(db, \"schools\", currentUser.uid, \"timetables\", `${currentTimetable.class}-${currentTimetable.section}`);\r\n      await setDoc(ref, { ...currentTimetable, updatedAt: serverTimestamp() });\r\n      allTimetables = allTimetables.filter(timetable => (timetable.id || `${timetable.class || \"\"}-${timetable.section || \"\"}`) !== currentTimetableDocId());\r\n      allTimetables.push({ id: currentTimetableDocId(), ...currentTimetable });\r\n      allTimetables = dedupeTimetables(allTimetables);\r\n      toast(\"Subjects saved successfully!\");\r\n    } catch(e) {\r\n      console.error(e);\r\n      toast(\"Error saving subjects\", \"error\");\r\n    }\r\n    showLoading(false);\r\n  };\r\n\r\n  window.loadTimetable = async function () {\r\n    const cls = document.getElementById(\"classSelect\").value;\r\n    const sec = document.getElementById(\"sectionSelect\").value;\r\n    if (!cls || !sec) { toast(\"Please select a class and section\", \"error\"); return; }\r\n    showLoading(true, \"Loading timetable...\");\r\n    try {\r\n      await nextPaint();\r\n      const ref  = doc(db, \"schools\", currentUser.uid, \"timetables\", `${cls}-${sec}`);\r\n      const [snap] = await Promise.all([getDoc(ref), loadSchoolSubjects()]);\r\n      if (snap.exists()) {\r\n        currentTimetable = snap.data();\r\n        currentTimetable.class = currentTimetable.class || cls;\r\n        currentTimetable.section = currentTimetable.section || sec;\r\n        normalizeTimetablePeriods();\r\n        clearInactiveTeacherSlots();\r\n      } else {\r\n        currentTimetable = { class: cls, section: sec, schedule: createEmptySchedule(), periodTimes: createEmptyPeriodTimes() };\r\n        syncPeriodTimesToSlots();\r\n      }\r\n      renderTimetable();\r\n      document.getElementById(\"statsBar\").style.display = \"flex\";\r\n      document.getElementById(\"statClass\").textContent   = cls;\r\n      document.getElementById(\"statSection\").textContent = sec;\r\n      refreshTimetableCache().catch(console.error);\r\n    } catch(e) {\r\n      toast(\"Failed to load timetable\", \"error\");\r\n    }\r\n    showLoading(false);\r\n  };\r\n\r\n  // ── ADD PERIOD ──\r\n  window.addPeriod = function () {\r\n    if (!currentTimetable) { toast(\"Load a timetable first\", \"error\"); return; }\r\n    normalizeTimetablePeriods();\r\n    const periods = getSortedPeriodKeys();\r\n    const next    = periods.length + 1;\r\n    currentTimetable.periodTimes = currentTimetable.periodTimes || {};\r\n    currentTimetable.periodTimes[`Period ${next}`] = { startTime: \"\", endTime: \"\" };\r\n    days.forEach(day => {\r\n      currentTimetable.schedule[day][`Period ${next}`] = { subject: \"\", teacherUid: \"\", teacherId: \"\", teacherName: \"\", startTime: \"\", endTime: \"\" };\r\n    });\r\n    renderTimetable();\r\n    toast(`Period ${next} added`);\r\n  };\r\n\r\n  // ── REMOVE PERIOD ──\r\n  window.removePeriod = function (periodNum) {\r\n    if (!currentTimetable) return;\r\n    const key = `Period ${periodNum}`;\r\n    days.forEach(day => { delete currentTimetable.schedule[day][key]; });\r\n    if (currentTimetable.periodTimes) delete currentTimetable.periodTimes[key];\r\n    normalizeTimetablePeriods();\r\n    renderTimetable();\r\n    toast(`Period ${periodNum} removed`);\r\n  };\r\n\r\n  // ── UPDATE SLOT ──\r\n  window.updateSlot = function (day, period, field, value) {\r\n    currentTimetable.schedule[day][period][field] = value;\r\n    if (field === \"teacherName\") {\r\n      currentTimetable.schedule[day][period].teacherUid = \"\";\r\n      currentTimetable.schedule[day][period].teacherId = \"\";\r\n      currentTimetable.schedule[day][period].teacherEmail = \"\";\r\n      const badge = document.getElementById(`tid-${day}-${period.replace(\" \",\"_\")}`);\r\n      if (badge) badge.textContent = \"—\";\r\n    }\r\n  };\r\n\r\n  window.updatePeriodTime = function (period, field, value) {\r\n    if (![\"startTime\", \"endTime\"].includes(field)) return;\r\n    const time = getPeriodTime(period);\r\n    time[field] = value;\r\n    syncPeriodTimesToSlots();\r\n    updatePeriodTimeDisplay(period);\r\n  };\r\n\r\n  function updatePeriodTimeDisplay(period) {\r\n    const slot = getPeriodTime(period);\r\n    const el   = document.getElementById(`time-display-${period.replace(\" \",\"_\")}`);\r\n    if (!el) return;\r\n    if (slot.startTime && slot.endTime) {\r\n      el.textContent = `${slot.startTime} – ${slot.endTime}`;\r\n    } else if (slot.startTime) {\r\n      el.textContent = `From ${slot.startTime}`;\r\n    } else {\r\n      el.textContent = \"\";\r\n    }\r\n  }\r\n\r\n  // ── SEARCH TEACHER ──\r\n  window.searchTeacher = function (input, day, period) {\r\n    const value     = input.value.toLowerCase();\r\n    const resultBox = document.getElementById(`tr-${day}-${period.replace(\" \",\"_\")}`);\r\n    resultBox.innerHTML = \"\";\r\n    if (!value) return;\r\n    const filtered = teachers.filter(t =>\r\n      (t.name || \"\").toLowerCase().includes(value) ||\r\n      (t.teacherId || \"\").toLowerCase().includes(value)\r\n    );\r\n    filtered.slice(0, 6).forEach(teacher => {\r\n      const conflict = findTeacherConflict(teacher, day, period);\r\n      const div = document.createElement(\"div\");\r\n      div.className = `teacher-result-item${conflict ? \" busy\" : \"\"}`;\r\n      div.innerHTML = `<div class=\"t-name\">${escHtml(teacher.name)}</div><div class=\"t-id\">${conflict ? escHtml(conflictMessage(teacher, conflict, day, period)) : escHtml(teacher.teacherId || teacher.uid)}</div>`;\r\n      div.onclick = () => {\r\n        if (conflict) {\r\n          toast(conflictMessage(teacher, conflict, day, period), \"error\");\r\n          return;\r\n        }\r\n        input.value = teacher.name;\r\n        currentTimetable.schedule[day][period].teacherUid  = teacher.uid;\r\n        currentTimetable.schedule[day][period].teacherId   = teacher.teacherId || teacher.uid;\r\n        currentTimetable.schedule[day][period].teacherName = teacher.name;\r\n        currentTimetable.schedule[day][period].teacherEmail = teacher.email || \"\";\r\n        // Update badge\r\n        const badge = document.getElementById(`tid-${day}-${period.replace(\" \",\"_\")}`);\r\n        if (badge) badge.textContent = teacher.teacherId || teacher.uid;\r\n        resultBox.innerHTML = \"\";\r\n      };\r\n      resultBox.appendChild(div);\r\n    });\r\n  };\r\n\r\n  // ── RENDER ──\r\n  function renderTimetableLegacyDailyTime() {\r\n    const container = document.getElementById(\"timetableContainer\");\r\n    normalizeTimetablePeriods();\r\n    const periods = getSortedPeriodKeys();\r\n\r\n    document.getElementById(\"statPeriods\").textContent = periods.length;\r\n\r\n    const dayIcons = {\r\n      Monday:    `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><line x1=\"12\" y1=\"1\" x2=\"12\" y2=\"3\"/><line x1=\"12\" y1=\"21\" x2=\"12\" y2=\"23\"/><line x1=\"4.22\" y1=\"4.22\" x2=\"5.64\" y2=\"5.64\"/><line x1=\"18.36\" y1=\"18.36\" x2=\"19.78\" y2=\"19.78\"/><line x1=\"1\" y1=\"12\" x2=\"3\" y2=\"12\"/><line x1=\"21\" y1=\"12\" x2=\"23\" y2=\"12\"/><line x1=\"4.22\" y1=\"19.78\" x2=\"5.64\" y2=\"18.36\"/><line x1=\"18.36\" y1=\"5.64\" x2=\"19.78\" y2=\"4.22\"/></svg>`,\r\n      Tuesday:   `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 3v1m0 16v1M4.22 4.22l.707.707m12.728 12.728.707.707M3 12h1m16 0h1M4.927 19.073l.707-.707M18.364 5.636l.707-.707\"/></svg>`,\r\n      Wednesday: `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></svg>`,\r\n      Thursday:  `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg>`,\r\n      Friday:    `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"/><line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"/></svg>`,\r\n      Saturday:  `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 2a10 10 0 1 0 10 10H12z\"/></svg>`,\r\n    };\r\n\r\n    let html = `<div class=\"table-wrapper\"><table>\r\n      <thead><tr>\r\n        <th>Period / Time</th>\r\n        ${days.map(d => `<th><div class=\"day-icon\">${dayIcons[d] || \"\"} ${d}</div></th>`).join(\"\")}\r\n      </tr></thead>\r\n      <tbody>`;\r\n\r\n    periods.forEach(period => {\r\n      const pNum   = period.replace(\"Period \",\"\");\r\n      const pKey   = period.replace(\" \",\"_\");\r\n      const monday = currentTimetable.schedule[\"Monday\"][period];\r\n      const timeDisplay = (monday.startTime && monday.endTime)\r\n        ? `${monday.startTime} – ${monday.endTime}`\r\n        : (monday.startTime ? `From ${monday.startTime}` : \"\");\r\n\r\n      html += `<tr>\r\n        <td>\r\n          <div class=\"period-cell\">\r\n            <div class=\"period-num\">\r\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"2.2\" style=\"vertical-align:-2px;margin-right:4px\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n              ${period}\r\n            </div>\r\n            <div class=\"period-time-display\" id=\"time-display-${pKey}\">${timeDisplay}</div>\r\n            ${periods.length > 1 ? `<button class=\"btn btn-danger period-remove\" onclick=\"removePeriod(${pNum})\">\r\n              <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-1 14H6L5 6\"/><path d=\"M10 11v6\"/><path d=\"M14 11v6\"/><path d=\"M9 6V4h6v2\"/></svg>\r\n              Remove\r\n            </button>` : \"\"}\r\n          </div>\r\n        </td>`;\r\n\r\n      days.forEach(day => {\r\n        const slot    = currentTimetable.schedule[day][period] || {};\r\n        const slotKey = `${day}-${pKey}`;\r\n        html += `<td>\r\n          <div class=\"slot-cell\">\r\n\r\n            <div class=\"field-label-small\">\r\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\r\n              Subject\r\n            </div>\r\n            <input class=\"slot-input subject-input\" type=\"text\" placeholder=\"e.g. Mathematics\"\r\n              value=\"${escHtml(slot.subject || '')}\"\r\n              onchange=\"updateSlot('${day}','${period}','subject',this.value)\">\r\n\r\n            <div class=\"field-label-small\" style=\"margin-top:2px\">\r\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n              <span style=\"color:var(--gold)\">Start</span>\r\n            </div>\r\n            <input class=\"slot-input time-input\" type=\"text\"\r\n              value=\"${escHtml(slot.startTime || '')}\"\r\n              onchange=\"updateSlot('${day}','${period}','startTime',this.value)\">\r\n\r\n            <div class=\"field-label-small\">\r\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n              <span style=\"color:var(--gold)\">End</span>\r\n            </div>\r\n            <input class=\"slot-input time-input\" type=\"text\"\r\n              value=\"${escHtml(slot.endTime || '')}\"\r\n              onchange=\"updateSlot('${day}','${period}','endTime',this.value)\">\r\n\r\n            <div class=\"field-label-small\" style=\"margin-top:2px\">\r\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></svg>\r\n              Teacher\r\n            </div>\r\n            <div class=\"teacher-search-wrap\">\r\n              <input class=\"slot-input\" type=\"text\" placeholder=\"Search teacher…\"\r\n                value=\"${escHtml(slot.teacherName || '')}\"\r\n                oninput=\"updateSlot('${day}','${period}','teacherName',this.value); searchTeacher(this,'${day}','${period}')\">\r\n              <div class=\"teacher-results\" id=\"tr-${slotKey}\"></div>\r\n            </div>\r\n\r\n            <div class=\"teacher-id-badge\">\r\n              <svg width=\"9\" height=\"9\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"2\" y=\"7\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M16 3H8l-2 4h12z\"/></svg>\r\n              <span id=\"tid-${slotKey}\">${escHtml(getTeacherReadableId(slot))}</span>\r\n            </div>\r\n          </div>\r\n        </td>`;\r\n      });\r\n      html += `</tr>`;\r\n    });\r\n\r\n    html += `</tbody></table></div>`;\r\n    container.innerHTML = html;\r\n  }\r\n\r\n  function renderTimetable() {\r\n    const container = document.getElementById(\"timetableContainer\");\r\n    normalizeTimetablePeriods();\r\n    const periods = getSortedPeriodKeys();\r\n\r\n    document.getElementById(\"statPeriods\").textContent = periods.length;\r\n\r\n    const dayIcons = {\r\n      Monday:    `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><line x1=\"12\" y1=\"1\" x2=\"12\" y2=\"3\"/><line x1=\"12\" y1=\"21\" x2=\"12\" y2=\"23\"/><line x1=\"4.22\" y1=\"4.22\" x2=\"5.64\" y2=\"5.64\"/><line x1=\"18.36\" y1=\"18.36\" x2=\"19.78\" y2=\"19.78\"/><line x1=\"1\" y1=\"12\" x2=\"3\" y2=\"12\"/><line x1=\"21\" y1=\"12\" x2=\"23\" y2=\"12\"/><line x1=\"4.22\" y1=\"19.78\" x2=\"5.64\" y2=\"18.36\"/><line x1=\"18.36\" y1=\"5.64\" x2=\"19.78\" y2=\"4.22\"/></svg>`,\r\n      Tuesday:   `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 3v1m0 16v1M4.22 4.22l.707.707m12.728 12.728.707.707M3 12h1m16 0h1M4.927 19.073l.707-.707M18.364 5.636l.707-.707\"/></svg>`,\r\n      Wednesday: `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></svg>`,\r\n      Thursday:  `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg>`,\r\n      Friday:    `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"/><line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"/></svg>`,\r\n      Saturday:  `<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 2a10 10 0 1 0 10 10H12z\"/></svg>`\r\n    };\r\n\r\n    let html = `<div class=\"table-wrapper\"><table>\r\n      <thead><tr>\r\n        <th>Period / Time</th>\r\n        ${days.map(d => `<th><div class=\"day-icon\">${dayIcons[d] || \"\"} ${d}</div></th>`).join(\"\")}\r\n      </tr></thead>\r\n      <tbody>`;\r\n\r\n    periods.forEach(period => {\r\n      const pNum = period.replace(\"Period \", \"\");\r\n      const pKey = period.replace(\" \", \"_\");\r\n      const periodTime = getPeriodTime(period);\r\n      const timeDisplay = getTimeLabel(periodTime);\r\n\r\n      html += `<tr>\r\n        <td>\r\n          <div class=\"period-cell\">\r\n            <div class=\"period-num\">\r\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"2.2\" style=\"vertical-align:-2px;margin-right:4px\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n              ${period}\r\n            </div>\r\n            <div class=\"period-time-display\" id=\"time-display-${pKey}\">${escHtml(timeDisplay)}</div>\r\n            <div class=\"period-time-controls\">\r\n              <div class=\"field-label-small\">\r\n                <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n                <span style=\"color:var(--gold)\">Start</span>\r\n              </div>\r\n              <input class=\"slot-input time-input\" type=\"text\" value=\"${escHtml(periodTime.startTime || \"\")}\" onchange=\"updatePeriodTime('${period}','startTime',this.value)\">\r\n              <div class=\"field-label-small\">\r\n                <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n                <span style=\"color:var(--gold)\">End</span>\r\n              </div>\r\n              <input class=\"slot-input time-input\" type=\"text\" value=\"${escHtml(periodTime.endTime || \"\")}\" onchange=\"updatePeriodTime('${period}','endTime',this.value)\">\r\n            </div>\r\n            ${periods.length > 1 ? `<button class=\"btn btn-danger period-remove\" onclick=\"removePeriod(${pNum})\">\r\n              <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-1 14H6L5 6\"/><path d=\"M10 11v6\"/><path d=\"M14 11v6\"/><path d=\"M9 6V4h6v2\"/></svg>\r\n              Remove\r\n            </button>` : \"\"}\r\n          </div>\r\n        </td>`;\r\n\r\n      days.forEach(day => {\r\n        const slot = currentTimetable.schedule[day][period] || {};\r\n        const slotKey = `${day}-${pKey}`;\r\n        html += `<td>\r\n          <div class=\"slot-cell\">\r\n            <div class=\"field-label-small\">\r\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\r\n              Subject\r\n            </div>\r\n            <input class=\"slot-input subject-input\" type=\"text\" placeholder=\"e.g. Mathematics\" value=\"${escHtml(slot.subject || \"\")}\" onchange=\"updateSlot('${day}','${period}','subject',this.value)\">\r\n\r\n            <div class=\"field-label-small\" style=\"margin-top:2px\">\r\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></svg>\r\n              Teacher\r\n            </div>\r\n            <div class=\"teacher-search-wrap\">\r\n              <input class=\"slot-input\" type=\"text\" placeholder=\"Search teacher...\" value=\"${escHtml(slot.teacherName || \"\")}\" oninput=\"updateSlot('${day}','${period}','teacherName',this.value); searchTeacher(this,'${day}','${period}')\">\r\n              <div class=\"teacher-results\" id=\"tr-${slotKey}\"></div>\r\n            </div>\r\n\r\n            <div class=\"teacher-id-badge\">\r\n              <svg width=\"9\" height=\"9\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"2\" y=\"7\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M16 3H8l-2 4h12z\"/></svg>\r\n              <span id=\"tid-${slotKey}\">${escHtml(getTeacherReadableId(slot))}</span>\r\n            </div>\r\n          </div>\r\n        </td>`;\r\n      });\r\n      html += `</tr>`;\r\n    });\r\n\r\n    html += `</tbody></table></div>`;\r\n    container.innerHTML = html;\r\n  }\r\n\r\n  function sortPeriodKeys(periods = []) {\r\n    return periods.slice().sort((a, b) =>\r\n      (parseInt(String(a).replace(\"Period \", \"\"), 10) || 0) -\r\n      (parseInt(String(b).replace(\"Period \", \"\"), 10) || 0)\r\n    );\r\n  }\r\n\r\n  function getTimeLabel(slot = {}) {\r\n    if (slot.startTime && slot.endTime) return `${formatTime12(slot.startTime)} - ${formatTime12(slot.endTime)}`;\r\n    if (slot.startTime) return `From ${formatTime12(slot.startTime)}`;\r\n    if (slot.endTime) return `Until ${formatTime12(slot.endTime)}`;\r\n    return \"\";\r\n  }\r\n\r\n  function formatTime12(value) {\r\n    const match = String(value || \"\").trim().match(/^(\\d{1,2}):(\\d{2})/);\r\n    if (!match) return String(value || \"\");\r\n    let hours = Number(match[1]);\r\n    const minutes = match[2];\r\n    if (!Number.isFinite(hours)) return String(value || \"\");\r\n    const suffix = hours >= 12 ? \"PM\" : \"AM\";\r\n    hours = hours % 12 || 12;\r\n    return `${hours}:${minutes} ${suffix}`;\r\n  }\r\n\r\n  function timeParts12(value) {\r\n    const match = String(value || \"\").trim().match(/^(\\d{1,2}):(\\d{2})/);\r\n    if (!match) return { hour: \"\", minute: \"\", meridiem: \"AM\" };\r\n    const rawHour = Number(match[1]);\r\n    const minute = match[2];\r\n    if (!Number.isFinite(rawHour)) return { hour: \"\", minute: \"\", meridiem: \"AM\" };\r\n    return {\r\n      hour: String(rawHour % 12 || 12),\r\n      minute,\r\n      meridiem: rawHour >= 12 ? \"PM\" : \"AM\"\r\n    };\r\n  }\r\n\r\n  function toTime24(hour, minute, meridiem) {\r\n    let value = Number(hour || 0);\r\n    if (!Number.isFinite(value) || value < 1 || value > 12 || !minute) return \"\";\r\n    const suffix = meridiem === \"PM\" ? \"PM\" : \"AM\";\r\n    if (suffix === \"AM\" && value === 12) value = 0;\r\n    if (suffix === \"PM\" && value !== 12) value += 12;\r\n    return `${String(value).padStart(2, \"0\")}:${String(minute).padStart(2, \"0\")}`;\r\n  }\r\n\r\n  function timeOptions(selectedValue, values) {\r\n    return values.map(value => `<option value=\"${escHtml(value)}\" ${String(value) === String(selectedValue) ? \"selected\" : \"\"}>${escHtml(value)}</option>`).join(\"\");\r\n  }\r\n\r\n  function renderTime12Controls(period, field, value) {\r\n    const parts = timeParts12(value);\r\n    const id = `${period.replace(/\\s+/g, \"_\")}_${field}`;\r\n    const hours = Array.from({ length: 12 }, (_, index) => String(index + 1));\r\n    const minutes = Array.from({ length: 12 }, (_, index) => String(index * 5).padStart(2, \"0\"));\r\n    return `<div class=\"time-12-controls\" data-period=\"${escHtml(period)}\" data-field=\"${escHtml(field)}\">\r\n      <select class=\"slot-input time-input\" id=\"${id}_hour\" aria-label=\"${escHtml(period)} ${field} hour\" onchange=\"updatePeriodTime12('${period}','${field}')\">\r\n        <option value=\"\">Hr</option>${timeOptions(parts.hour, hours)}\r\n      </select>\r\n      <select class=\"slot-input time-input\" id=\"${id}_minute\" aria-label=\"${escHtml(period)} ${field} minute\" onchange=\"updatePeriodTime12('${period}','${field}')\">\r\n        <option value=\"\">Min</option>${timeOptions(parts.minute, minutes)}\r\n      </select>\r\n      <select class=\"slot-input time-input\" id=\"${id}_meridiem\" aria-label=\"${escHtml(period)} ${field} AM PM\" onchange=\"updatePeriodTime12('${period}','${field}')\">\r\n        ${timeOptions(parts.meridiem, [\"AM\", \"PM\"])}\r\n      </select>\r\n    </div>`;\r\n  }\r\n\r\n  window.updatePeriodTime12 = function (period, field) {\r\n    const id = `${period.replace(/\\s+/g, \"_\")}_${field}`;\r\n    const hour = document.getElementById(`${id}_hour`)?.value || \"\";\r\n    const minute = document.getElementById(`${id}_minute`)?.value || \"\";\r\n    const meridiem = document.getElementById(`${id}_meridiem`)?.value || \"AM\";\r\n    updatePeriodTime(period, field, toTime24(hour, minute, meridiem));\r\n  };\r\n\r\n  window.closeTeacherTimetableView = function() {\r\n    document.getElementById(\"teacherViewCard\").classList.remove(\"show\");\r\n    document.getElementById(\"teacherTimetableView\").innerHTML = \"\";\r\n  };\r\n\r\n  window.viewTeacherTimetable = async function() {\r\n    const teacherUid = document.getElementById(\"teacherViewSelect\").value;\r\n    if (!teacherUid) {\r\n      toast(\"Please select a teacher first\", \"error\");\r\n      return;\r\n    }\r\n\r\n    const teacher = teachers.find(t => t.uid === teacherUid);\r\n    if (!teacher) {\r\n      toast(\"Teacher not found\", \"error\");\r\n      return;\r\n    }\r\n\r\n    showLoading(true, \"Loading teacher timetable...\");\r\n    try {\r\n      await nextPaint();\r\n      const timetables = await refreshTimetableCache(true);\r\n      const teacherSchedule = {};\r\n      let slotCount = 0;\r\n      const classSet = new Set();\r\n      const seenSlots = new Set();\r\n\r\n      timetables.forEach(timetable => {\r\n        const className = timetable.class || String(timetable.id).split(\"-\")[0] || \"\";\r\n        const sectionName = timetable.section || String(timetable.id).split(\"-\").slice(1).join(\"-\") || \"\";\r\n        const classLabel = sectionName ? `${className}-${sectionName}` : className;\r\n\r\n        Object.entries(timetable.schedule || {}).forEach(([day, daySlots]) => {\r\n          Object.entries(daySlots || {}).forEach(([period, slot]) => {\r\n            if (!slotBelongsToTeacher(slot, teacher)) return;\r\n            const commonTime = timetable.periodTimes?.[period] || {};\r\n            const uniqueSlotKey = `${timetableKey(timetable)}|${day}|${period}|${teacher.uid}`;\r\n            if (seenSlots.has(uniqueSlotKey)) return;\r\n            seenSlots.add(uniqueSlotKey);\r\n            if (!teacherSchedule[day]) teacherSchedule[day] = {};\r\n            if (!teacherSchedule[day][period]) teacherSchedule[day][period] = [];\r\n            teacherSchedule[day][period].push({\r\n              ...slot,\r\n              startTime: commonTime.startTime || slot.startTime || \"\",\r\n              endTime: commonTime.endTime || slot.endTime || \"\",\r\n              classLabel,\r\n              class: className,\r\n              section: sectionName\r\n            });\r\n            slotCount += 1;\r\n            if (classLabel) classSet.add(classLabel);\r\n          });\r\n        });\r\n      });\r\n\r\n      const card = document.getElementById(\"teacherViewCard\");\r\n      document.getElementById(\"teacherViewTitle\").textContent =\r\n        `${teacher.name} - Full Timetable`;\r\n      document.getElementById(\"teacherViewMeta\").textContent =\r\n        `Teacher ID: ${teacher.teacherId || teacher.uid} | ${slotCount} lecture${slotCount === 1 ? \"\" : \"s\"} | ${classSet.size} class${classSet.size === 1 ? \"\" : \"es\"}`;\r\n\r\n      document.getElementById(\"teacherTimetableView\").innerHTML = renderTeacherReadonlyTimetable(teacherSchedule);\r\n      card.classList.add(\"show\");\r\n      card.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\r\n    } catch (error) {\r\n      console.error(error);\r\n      toast(\"Failed to load teacher timetable\", \"error\");\r\n    }\r\n    showLoading(false);\r\n  };\r\n\r\n  function renderTeacherReadonlyTimetable(schedule = {}) {\r\n    const scheduleDays = days.filter(day => schedule[day]);\r\n    const allPeriods = sortPeriodKeys([...new Set(scheduleDays.flatMap(day => Object.keys(schedule[day] || {})))]);\r\n\r\n    if (!scheduleDays.length || !allPeriods.length) {\r\n      return `<div class=\"empty-state\" style=\"padding:2rem;\"><h3>No timetable found</h3><p>No periods are assigned to this teacher yet.</p></div>`;\r\n    }\r\n\r\n    let html = `<div class=\"table-wrapper\"><table>\r\n      <thead><tr>\r\n        <th>Period / Time</th>\r\n        ${days.map(day => `<th>${day}</th>`).join(\"\")}\r\n      </tr></thead><tbody>`;\r\n\r\n    allPeriods.forEach(period => {\r\n      html += `<tr><td><div class=\"period-cell\"><div class=\"period-num\">${escHtml(period)}</div></div></td>`;\r\n      days.forEach(day => {\r\n        const slots = schedule[day]?.[period] || [];\r\n        if (!slots.length) {\r\n          html += `<td><span style=\"color:var(--muted);font-size:0.8rem;\">—</span></td>`;\r\n          return;\r\n        }\r\n        html += `<td>${slots.map(slot => `\r\n          <div class=\"readonly-slot\">\r\n            <strong>${escHtml(slot.subject || \"Lecture\")}</strong>\r\n            <div>Class: ${escHtml(slot.classLabel || \"—\")}</div>\r\n            <div>Teacher ID: ${escHtml(getTeacherReadableId(slot))}</div>\r\n          </div>\r\n        `).join('<div style=\"height:8px\"></div>')}</td>`;\r\n      });\r\n      html += `</tr>`;\r\n    });\r\n\r\n    html += `</tbody></table></div>`;\r\n    return html;\r\n  }\r\n\r\n  function escHtml(s) {\r\n    return String(s).replace(/&/g,\"&amp;\").replace(/\"/g,\"&quot;\").replace(/</g,\"&lt;\").replace(/>/g,\"&gt;\");\r\n  }\r\n\r\n  // ── SAVE ──\r\n  renderTimetable = function renderTimetableFlipped() {\r\n    const container = document.getElementById(\"timetableContainer\");\r\n    normalizeTimetablePeriods();\r\n    const periods = getSortedPeriodKeys();\r\n    document.getElementById(\"statPeriods\").textContent = periods.length;\r\n\r\n    let html = `<div class=\"table-wrapper\"><table><thead><tr><th>Day</th>`;\r\n    html += periods.map(period => {\r\n      const periodTime = getPeriodTime(period);\r\n      const timeLabel = getTimeLabel(periodTime);\r\n      const pNum = period.replace(\"Period \", \"\");\r\n      return `<th><div class=\"period-cell\"><div class=\"period-num\">${escHtml(period)}</div><div class=\"period-time-display\" id=\"time-display-${period.replace(\" \", \"_\")}\">${escHtml(timeLabel)}</div><div class=\"period-time-controls\"><div class=\"field-label-small\"><span style=\"color:var(--gold)\">Start</span></div>${renderTime12Controls(period, \"startTime\", periodTime.startTime || \"\")}<div class=\"field-label-small\"><span style=\"color:var(--gold)\">End</span></div>${renderTime12Controls(period, \"endTime\", periodTime.endTime || \"\")}${periods.length > 1 ? `<button class=\"btn btn-danger period-remove\" onclick=\"removePeriod(${pNum})\">Remove</button>` : \"\"}</div></div></th>`;\r\n    }).join(\"\");\r\n    html += `</tr></thead><tbody>`;\r\n\r\n    days.forEach(day => {\r\n      html += `<tr><td><strong>${escHtml(day)}</strong></td>`;\r\n      periods.forEach(period => {\r\n        const slot = currentTimetable.schedule[day]?.[period] || {};\r\n        const slotKey = `${day}-${period.replace(/ /g, \"_\")}`;\r\n        const teacherUid = slot.teacherUid || slot.teacherId || \"\";\r\n        html += `<td><div class=\"slot-cell\">\r\n          <div class=\"field-label-small\">Subject</div>\r\n          <select class=\"slot-input subject-input\" onchange=\"onSlotSubjectChange('${day}','${period}',this)\">${subjectOptions(slot.subject || \"\")}</select>\r\n          <div class=\"field-label-small\" style=\"margin-top:2px\">Teacher</div>\r\n          <select class=\"slot-input teacher-select\" id=\"tsel-${slotKey}\" onchange=\"onSlotTeacherChange('${day}','${period}',this)\">${teacherSelectOptions(slot.subject || \"\", teacherUid, day, period)}</select>\r\n          <div class=\"teacher-id-badge\"><span id=\"tid-${slotKey}\">${escHtml(getTeacherReadableId(slot))}</span></div>\r\n        </div></td>`;\r\n      });\r\n      html += `</tr>`;\r\n    });\r\n\r\n    html += `</tbody></table></div>`;\r\n    container.innerHTML = html;\r\n  };\r\n\r\n  renderTeacherReadonlyTimetable = function renderTeacherReadonlyTimetableFlipped(schedule = {}) {\r\n    const scheduleDays = days.filter(day => schedule[day]);\r\n    const allPeriods = sortPeriodKeys([...new Set(scheduleDays.flatMap(day => Object.keys(schedule[day] || {})))]);\r\n    if (!scheduleDays.length || !allPeriods.length) return `<div class=\"empty-state\" style=\"padding:2rem;\"><h3>No timetable found</h3><p>No periods are assigned to this teacher yet.</p></div>`;\r\n    let html = `<div class=\"table-wrapper\"><table><thead><tr><th>Day</th>`;\r\n    allPeriods.forEach(period => {\r\n      const firstSlot = scheduleDays.flatMap(day => schedule[day]?.[period] || []).find(slot => getTimeLabel(slot)) || {};\r\n      const time = getTimeLabel(firstSlot);\r\n      html += `<th><strong>${escHtml(period)}</strong>${time ? `<div class=\"class-info\">${escHtml(time)}</div>` : \"\"}</th>`;\r\n    });\r\n    html += `</tr></thead><tbody>`;\r\n    scheduleDays.forEach(day => {\r\n      html += `<tr><td><strong>${escHtml(day)}</strong></td>`;\r\n      allPeriods.forEach(period => {\r\n        const slots = schedule[day]?.[period] || [];\r\n        html += slots.length ? `<td>${slots.map(slot => `<div class=\"readonly-slot\"><strong>${escHtml(slot.subject || \"Lecture\")}</strong><div>Class: ${escHtml(slot.classLabel || \"-\")}</div><div>Teacher ID: ${escHtml(getTeacherReadableId(slot))}</div></div>`).join('<div style=\"height:8px\"></div>')}</td>` : `<td><span style=\"color:var(--muted);font-size:0.8rem;\">-</span></td>`;\r\n      });\r\n      html += `</tr>`;\r\n    });\r\n    html += `</tbody></table></div>`;\r\n    return html;\r\n  };\r\n\r\n  window.saveTimetable = async function () {\r\n    if (!currentTimetable) { toast(\"Load a timetable first\", \"error\"); return; }\r\n    showLoading(true, \"Saving timetable...\");\r\n    try {\r\n      await nextPaint();\r\n      normalizeTimetablePeriods();\r\n      syncPeriodTimesToSlots();\r\n      await refreshTimetableCache(true);\r\n      if (!validateNoTeacherConflicts()) {\r\n        showLoading(false);\r\n        return;\r\n      }\r\n      const ref = doc(db, \"schools\", currentUser.uid, \"timetables\",\r\n        `${currentTimetable.class}-${currentTimetable.section}`);\r\n      await setDoc(ref, { ...currentTimetable, updatedAt: serverTimestamp() });\r\n      allTimetables = allTimetables.filter(timetable => (timetable.id || `${timetable.class || \"\"}-${timetable.section || \"\"}`) !== currentTimetableDocId());\r\n      allTimetables.push({ id: currentTimetableDocId(), ...currentTimetable });\r\n      allTimetables = dedupeTimetables(allTimetables);\r\n      toast(\"Timetable saved successfully!\");\r\n    } catch(e) {\r\n      console.error(e);\r\n      toast(\"Error saving timetable\", \"error\");\r\n    }\r\n    showLoading(false);\r\n  };\r\n\r\n  // ── AUTH ──\r\n  onAuthStateChanged(auth, async user => {\r\n    if (!user) { toast(\"Please login first\", \"error\"); return; }\r\n    currentUser = user;\r\n    showLoading(true, \"Preparing admin timetable...\");\r\n    await nextPaint();\r\n    await loadTeachers();\r\n    await loadSchoolSubjects();\r\n    await loadClasses();\r\n    showLoading(false);\r\n    refreshTimetableCache().catch(console.error);\r\n  });\r\n"},{"attributes":{"type":"module","src":"access-control.js"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""},{"attributes":{"src":"admin-shell.js?v=navbar-20260721"},"text":""}]};
